struct Agg { region: Str, qty: Int, cents: Int }

fn fmt_cents(c: Int) -> Str {
  if c < 0 { return "-" + fmt_cents(0 - c); }
  let frac = c % 100;
  let f = if frac < 10 { "0" + frac.to_str() } else { frac.to_str() };
  (c / 100).to_str() + "." + f
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("sales.csv")?.to_str();
  let mut rows: List<Agg> = [];
  let mut skipped = 0;
  for line in text.lines() {
    let t = line.trim();
    if t.len() == 0 { continue; }
    let parts = t.split(",");
    if parts.len() != 5 { skipped += 1; continue; }
    let Some(qty) = parts[3].trim().parse_int() else { skipped += 1; continue; };
    let Some(unit) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let region = parts[1].trim();
    let mut idx = -1;
    for i in 0..rows.len() {
      if rows[i].region == region { idx = i; }
    }
    if idx < 0 {
      rows.push(Agg { region: region, qty: qty, cents: qty * unit });
    } else {
      let old = rows[idx];
      rows[idx] = Agg { region: old.region, qty: old.qty + qty, cents: old.cents + qty * unit };
    }
  }
  rows.sort_by(|a: Agg, b: Agg| a.cents > b.cents || (a.cents == b.cents && a.region < b.region));
  let mut out = "";
  for r in rows {
    out = out + r.region + " " + r.qty.to_str() + " " + fmt_cents(r.cents) + "\n";
  }
  Ok(out + "skipped " + skipped.to_str())
