    let Some(unit) = parts[4].trim().parse_int() else { skipped += 1; continue; };
    let q = qtys.get(region).unwrap_or(0);
    qtys.insert(region, q + qty);
    let c = cents.get(region).unwrap_or(0);
    cents.insert(region, c + qty * unit);
  }

  let mut aggs: List<Agg> = [];
  for r in qtys.keys() {
    aggs.push(Agg {
      region: r,
      qty: qtys.get(r).unwrap_or(0),
