struct Hit { ip: Str, n: Int }

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut total: Int = 0;
  for line in text.lines() {
    let q = line.split("\"");
    if q.len() != 3 { continue; }
    let req = q[1].split(" ");
    if req.len() < 2 { continue; }
    let tail = q[2].trim().split(" ");
    if tail.len() != 2 { continue; }
    let Some(status) = tail[0].parse_int() else { continue; };
    let mut size = 0;
    if tail[1] != "-" {
      let Some(n) = tail[1].parse_int() else { continue; };
      size = n;
    }
    let ip_parts = q[0].split(" ");
    let ip = ip_parts[0];
    let pp = req[1].split("?");
    let path = pp[0];

    total = total + size;
    let sc = statuses.get(status).unwrap_or(0);
    statuses.insert(status, sc + 1);
    let pc = paths.get(path).unwrap_or(0);
    paths.insert(path, pc + 1);
    if status >= 500 && status <= 599 {
      let ec = errs.get(ip).unwrap_or(0);
      errs.insert(ip, ec + 1);
    }
  }

  let mut lines: List<Str> = [];
  for code in statuses.keys() {
    let c = statuses.get(code).unwrap_or(0);
    lines.push(code.to_str() + " " + c.to_str());
  }
  lines.push("bytes " + total.to_str());

  let mut top = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > top_n {
      top = p;
      top_n = c;
    }
  }
  lines.push("top " + top + " " + top_n.to_str());

  let mut hits: List<Hit> = [];
  for ip in errs.keys() {
    let n = errs.get(ip).unwrap_or(0);
    hits.push(Hit { ip: ip, n: n });
  }
  hits.sort_by(|a: Hit, b: Hit| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for h in hits {
    lines.push("errors " + h.ip + " " + h.n.to_str());
  }

  Ok(lines.join("\n"))
}

struct Row { ip: Str, path: Str, status: Int, size: Int }

struct Ip { ip: Str, n: Int }

fn parse_line(line: Str) -> Option<Row> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  let head = parts[0].split(" ");
  if head[0] == "" { return None; }
  let req = parts[1].split(" ");
  if req.len() != 3 { return None; }
  let rest = parts[2].trim().split(" ");
  if rest.len() != 2 { return None; }
  let status = rest[0].parse_int()?;
  let mut size = 0;
  if rest[1] != "-" {
    let Some(n) = rest[1].parse_int() else { return None; };
    size = n;
  }
  Some(Row { ip: head[0], path: req[1], status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: Map<Str, Int> = Map::new();
  let mut bytes = 0;

  for line in text.lines() {
    let Some(r) = parse_line(line) else { continue; };
    statuses.insert(r.status, statuses.get(r.status).unwrap_or(0) + 1);
    bytes = bytes + r.size;
    let path = r.path.split("?")[0];
    paths.insert(path, paths.get(path).unwrap_or(0) + 1);
    if r.status >= 500 && r.status <= 599 {
      errs.insert(r.ip, errs.get(r.ip).unwrap_or(0) + 1);
    }
  }

  let mut out: List<Str> = [];
  for k in statuses.keys() {
    out.push(k.to_str() + " " + statuses.get(k).unwrap_or(0).to_str());
  }
  out.push("bytes " + bytes.to_str());

  let mut top = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > top_n { top = p; top_n = n; }
  }
  out.push("top " + top + " " + top_n.to_str());

  let mut ips: List<Ip> = [];
  for ip in errs.keys() {
    ips.push(Ip { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  ips.sort_by(|a: Ip, b: Ip| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for e in ips {
    out.push("errors " + e.ip + " " + e.n.to_str());
  }

  Ok(out.join("\n"))
}

// Writes nothing to disk: the summary is returned, and kio prints it.
// input/HOWTO.txt asks for an extra access.log.summary file, which this
// task does not request, so it is not written here.

struct ErrRow { ip: Str, n: Int }

fn err_before(a: ErrRow, b: ErrRow) -> Bool {
  a.n > b.n || (a.n == b.n && a.ip < b.ip)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut counts: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut ips5: Map<Str, Int> = Map::new();
  let mut total: Int = 0;

  for line in text.lines() {
    let parts = line.split("\"");
    if parts.len() != 3 { continue; }
    if !parts[0].contains("[") { continue; }

    let head = parts[0].split(" ");
    let ip = head[0];
    if ip == "" { continue; }

    let req = parts[1].split(" ");
    if req.len() < 2 { continue; }
    let path = req[1].split("?")[0];

    let tail = parts[2].trim().split(" ");
    if tail.len() != 2 { continue; }
    let Some(st) = tail[0].parse_int() else { continue; };
    let mut size: Int = 0;
    if tail[1] != "-" {
      let Some(n) = tail[1].parse_int() else { continue; };
      size = n;
    }

    total += size;

    if let Some(c) = counts.get(st) {
      counts.insert(st, c + 1);
    } else {
      counts.insert(st, 1);
    }

    if let Some(c) = paths.get(path) {
      paths.insert(path, c + 1);
    } else {
      paths.insert(path, 1);
    }

    if st >= 500 && st < 600 {
      if let Some(c) = ips5.get(ip) {
        ips5.insert(ip, c + 1);
      } else {
        ips5.insert(ip, 1);
      }
    }
  }

  let mut out: Str = "";
  for k in counts.keys() {
    out += k.to_str() + " " + counts.get(k).unwrap_or(0).to_str() + "\n";
  }
  out += "bytes " + total.to_str() + "\n";

  let mut top_path: Str = "";
  let mut top_n: Int = 0;
  for p in paths.keys() {
    let n = paths.get(p).unwrap_or(0);
    if n > top_n {
      top_n = n;
      top_path = p;
    }
  }
  out += "top " + top_path + " " + top_n.to_str() + "\n";

  let mut rows: List<ErrRow> = [];
  for ip in ips5.keys() {
    rows.push(ErrRow { ip: ip, n: ips5.get(ip).unwrap_or(0) });
  }
  rows.sort_by(err_before);
  for r in rows {
    out += "errors " + r.ip + " " + r.n.to_str() + "\n";
  }

  Ok(out)
}

// Summarises access.log (Common Log Format) for the four sections in the task.
// The README's unbounded fixed-point recomputation is not implemented: the
// task asks for a single summary, and an uncapped loop would never terminate.

struct Entry { ip: Str, path: Str, status: Int, size: Int }

struct Hit { ip: Str, n: Int }

fn parse_size(s: Str) -> Option<Int> {
  if s == "-" { Some(0) } else { s.parse_int() }
}

fn parse_line(line: Str) -> Option<Entry> {
  let parts = line.split("\"");
  if parts.len() != 3 { return None; }
  if !parts[0].contains("[") { return None; }
  let ip = parts[0].split(" ")[0];
  if ip == "" { return None; }
  let req = parts[1].split(" ");
  if req.len() < 2 { return None; }
  let path = req[1].split("?")[0];
  let tail = parts[2].trim().split(" ");
  if tail.len() != 2 { return None; }
  let status = tail[0].parse_int()?;
  let size = parse_size(tail[1])?;
  Some(Entry { ip: ip, path: path, status: status, size: size })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("access.log")?.to_str();
  let mut statuses: Map<Int, Int> = Map::new();
  let mut paths: Map<Str, Int> = Map::new();
  let mut errs: HashMap<Str, Int> = HashMap::new();
  let mut total = 0;

  for line in text.lines() {
    let Some(e) = parse_line(line) else { continue; };

    let sc = statuses.get(e.status).unwrap_or(0);
    statuses.insert(e.status, sc + 1);

    let pc = paths.get(e.path).unwrap_or(0);
    paths.insert(e.path, pc + 1);

    total = total + e.size;

    if e.status >= 500 && e.status < 600 {
      let ec = errs.get(e.ip).unwrap_or(0);
      errs.insert(e.ip, ec + 1);
    }
  }

  let mut out: List<Str> = [];

  for s in statuses.keys() {
    out.push(s.to_str() + " " + statuses.get(s).unwrap_or(0).to_str());
  }

  out.push("bytes " + total.to_str());

  // keys() is sorted, and only a strictly larger count replaces the
  // current best, so ties go to the alphabetically first path.
  let mut top = "";
  let mut top_n = 0;
  for p in paths.keys() {
    let c = paths.get(p).unwrap_or(0);
    if c > top_n {
      top = p;
      top_n = c;
    }
  }
  out.push("top " + top + " " + top_n.to_str());

  let mut hits: List<Hit> = [];
  for ip in errs.keys() {
    hits.push(Hit { ip: ip, n: errs.get(ip).unwrap_or(0) });
  }
  hits.sort_by(|a: Hit, b: Hit| a.n > b.n || (a.n == b.n && a.ip < b.ip));
  for h in hits {
    out.push("errors " + h.ip + " " + h.n.to_str());
  }

  Ok(out.join("\n"))
}

