// Reads input/emails.txt and prints the distinct normalized valid addresses,
// sorted, then `invalid N`. It does not rewrite emails.txt: the grant is read-only.

fn normalize(line: Str) -> Option<Str> {
  let s = line.trim().to_lowercase();
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") || domain.starts_with(".") || domain.ends_with(".") {
    return None;
  }
  let base = if domain == "gmail.com" {
    match local.find("+") {
      Some(i) => local.slice(0, i),
      None => local,
    }
  } else {
    local
  };
  let clean = if domain == "gmail.com" { base.split(".").join("") } else { base };
  // A gmail local part that was only "+..." leaves nothing: invalid.
  if clean.len() == 0 { return None; }
  Some(clean + "@" + domain)
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("emails.txt")?.to_str();
  let mut seen: Map<Str, Bool> = Map::new();
  let mut invalid = 0;
  for line in text.lines() {
    if line.trim().len() == 0 { continue; }
    match normalize(line) {
      Some(addr) => { seen.insert(addr, true); }
      None => { invalid += 1; }
    }
  }
  let mut out: List<Str> = [];
  for addr in seen.keys() {
    out.push(addr);
  }
  out.push("invalid " + invalid.to_str());
  Ok(out.join("\n"))
}

// Reads input/emails.txt, prints the distinct normalized valid addresses
// sorted by byte order, then "invalid N". This program only reads the file.
// The NOTES.md request to rewrite emails.txt is not implemented here.

fn normalize(raw: Str) -> Option<Str> {
  let s = raw.trim().to_lowercase();
  let parts = s.split("@");
  if parts.len() != 2 { return None; }
  let local = parts[0];
  let domain = parts[1];
  if local.len() == 0 { return None; }
  if !domain.contains(".") { return None; }
  if domain.starts_with(".") || domain.ends_with(".") { return None; }
  if domain == "gmail.com" {
    let base = local.split("+")[0];
    return Some(base.replace(".", "") + "@" + domain);
  }
  Some(s)
}

