  c == "(" || c == "[" || c == "{"
}

fn check_line(line: Str) -> Str {
  let mut stack: List<Str> = [];
  let mut col = 0;
  for c in line.chars() {
    col = col + 1;
    if c == "(" {
      stack.push(")");
    } else if c == "[" {
      stack.push("]");
    } else if c == "{" {
      stack.push("}");
    } else if c == ")" || c == "]" || c == "}" {
      if stack.len() == 0 {
        return "col " + col.to_str() + ": unexpected " + c;
      }
      let top = stack.pop().unwrap_or("");
      if top != c {
        return "col " + col.to_str() + ": expected " + top + ", found " + c;
      }
    }
  }
  if stack.len() > 0 {
    let innermost = stack[stack.len() - 1];
    return "unclosed " + innermost;
  }
  "ok"
}

