  Ok("error " + n_err.to_str() + "\n"
    + "warn " + n_warn.to_str() + "\n"
    + "info " + n_info.to_str() + "\n"
    + "other " + n_other.to_str())
}

fn fields(line: Str) -> List<Str> {
  let mut out: List<Str> = [];
  for p in line.split(" ") {
    if p.len() > 0 { out.push(p); }
  }
  out
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("app.log")?.to_str();
  let mut err_out = "";
  let mut warn_out = "";
  let mut info_out = "";
