  Ok("error " + err_n.to_str() + "\n" + "warn " + warn_n.to_str() + "\n" + "info " + info_n.to_str() + "\n" + "other " + other_n.to_str())
}

// users.csv -> out/users.json. Writes only out/users.json: the input grant is read-only,
// so the README's request to also write input/users.json is not done here.

fn split_csv(line: Str) -> List<Str> {
  let cs = line.chars();
  let mut fields: List<Str> = [];
  let mut cur = "";
  let mut inq = false;
  let mut i = 0;
  while i < cs.len() {
    let c = cs[i];
    if inq {
      if c == "\"" {
        if i + 1 < cs.len() && cs[i + 1] == "\"" {
          cur = cur + "\"";
          i = i + 1;
        } else {
          inq = false;
        }
      } else {
        cur = cur + c;
      }
    } else {
      if c == "," {
        fields.push(cur);
        cur = "";
      } else if c == "\"" {
        inq = true;
      } else {
        cur = cur + c;
      }
    }
    i = i + 1;
  }
  fields.push(cur);
  fields
}

fn main(input: Dir, out: Dir) -> Result<Str, IoErr> {
  let text = input.read("users.csv")?.to_str();
  let mut objs: List<Json> = [];
  let mut rows = 0;
  let mut skipped = 0;
  let mut header = true;
  for line in text.lines() {
    if header {
      header = false;
      continue;
    }
    if line.trim().len() == 0 {
      continue;
    }
    let parts = split_csv(line);
    if parts.len() != 5 {
      skipped += 1;
      continue;
    }
    let Some(id) = parts[0].trim().parse_int() else {
      skipped += 1;
      continue;
    };
