// Adds this run's visits to the running totals in `counts`, then prints every
// page seen so far. The file is only read, as the grant says, so each run adds
// its visits again (the spec's example: a second run with the same file doubles
// the totals). The README's delete-after-counting step needs a write grant on
// `input`, which this program does not have.

struct Row { page: Str, total: Int }

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let bytes = match input.read("visits.txt") {
    Ok(b) => b,
    Err(IoErr::NotFound) => "".to_bytes(),
    Err(_) => return Err("cannot read visits.txt"),
  };
  let text = bytes.to_str();

  for line in text.lines() {
    let page = line.trim();
    if page.len() == 0 { continue; }
    let key = "page:" + page;
    counts.add(key, 1).map_err(|e| "cannot update counts")?;
  }

  let keys = counts.keys("page:").map_err(|e| "cannot list counts")?;
  let mut rows: List<Row> = [];
  for k in keys {
    let v = counts.get(k).map_err(|e| "cannot read counts")?;
    let total = match v {
      Some(b) => b.to_str().parse_int().unwrap_or(0),
      None => 0,
    };
    rows.push(Row { page: k.slice(5, k.len()), total: total });
  }

  rows.sort_by(|a, b| a.total > b.total || (a.total == b.total && a.page < b.page));

  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

// Adds each run's visits to the persistent totals. visits.txt is read but not
// deleted, because the task's example requires a second run on the same file
// to add its visits again (4 after two runs). The day1 README's consume-once
// rule would delete the file instead, which conflicts with that example.

struct Row { page: Str, total: Int }

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let text = match input.read("visits.txt") {
    Ok(b) => b.to_str(),
    Err(IoErr::NotFound) => "",
    Err(_) => return Err("cannot read visits.txt"),
  };

  let mut run: HashMap<Str, Int> = HashMap::new();
  for line in text.lines() {
    let page = line.trim();
    if page.len() == 0 { continue; }
    let n = match run.get(page) { Some(c) => c + 1, None => 1 };
    run.insert(page, n);
  }

  for page in run.keys() {
    let n = run.get(page).unwrap_or(0);
    match counts.add("visit:" + page, n) {
      Ok(_) => { },
      Err(_) => return Err("cannot update counts"),
    }
  }

  let keys: List<Str> = match counts.keys("visit:") {
    Ok(ks) => ks,
    Err(_) => return Err("cannot list counts"),
  };

  let mut rows: List<Row> = [];
  for k in keys {
    let Some(page) = k.strip_prefix("visit:") else { continue; };
    let stored = match counts.get(k) {
      Ok(v) => v,
      Err(_) => return Err("cannot read counts"),
    };
    let Some(b) = stored else { continue; };
    let Some(total) = b.to_str().parse_int() else { continue; };
    rows.push(Row { page: page, total: total });
  }

  rows.sort_by(|a: Row, b: Row| a.total > b.total || (a.total == b.total && a.page < b.page));

  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

// The day1/README.md asks for deleting input/visits.txt after reading it.
// That step is not in the task statement, so it is left out here: each run
// reads the file and adds its visits, which matches the stated example.

struct Row { page: Str, total: Int }

fn read_visits(input: Dir) -> Result<List<Str>, Str> {
  match input.read("visits.txt") {
    Ok(bytes) => {
      let text = bytes.to_str();
      Ok(text.lines())
    }
    Err(IoErr::NotFound) => Ok([]),
    Err(_) => Err("cannot read visits.txt"),
  }
}

fn tally(lines: List<Str>) -> Map<Str, Int> {
  let mut m: Map<Str, Int> = Map::new();
  for line in lines {
    let page = line.trim();
    if page == "" { continue; }
    let n = match m.get(page) { Some(c) => c + 1, None => 1 };
    m.insert(page, n);
  }
  m
}

fn store(counts: Kv, m: Map<Str, Int>) -> Result<(), Str> {
  for page in m.keys() {
    let n = m.get(page).unwrap_or(0);
    match counts.add("page:" + page, n) {
      Ok(_) => {}
      Err(_) => return Err("cannot update counts"),
    }
  }
  Ok(())
}

fn before(a: Row, b: Row) -> Bool {
  if a.total != b.total { return a.total > b.total; }
  a.page < b.page
}

fn report(counts: Kv) -> Result<Str, Str> {
  let keys = match counts.keys("page:") {
    Ok(ks) => ks,
    Err(_) => return Err("cannot list counts"),
  };
  let mut rows: List<Row> = [];
  for k in keys {
    let page = k.slice(5, k.len());
    match counts.get(k) {
      Ok(Some(v)) => rows.push(Row { page: page, total: v.to_str().parse_int().unwrap_or(0) }),
      Ok(None) => {}
      Err(_) => return Err("cannot read counts"),
    }
  }
  rows.sort_by(before);
  let mut lines: List<Str> = [];
  for r in rows {
    lines.push(r.page + " " + r.total.to_str());
  }
  Ok(lines.join("\n"))
}

fn main(input: Dir, counts: Kv) -> Result<Str, Str> {
  let lines = read_visits(input)?;
  let m = tally(lines);
  store(counts, m)?;
  report(counts)
}

struct Row { page: Str, total: Int }

fn count_visits(input: Dir, counts: Kv) -> Result<(), Str> {
  let bytes = input.read("visits.txt").map_err(|e| "cannot read visits.txt")?;
  for line in bytes.to_str().lines() {
    let page = line.trim();
    if page.len() == 0 { continue; }
    counts.add(page, 1).map_err(|e| "cannot update counts")?;
  }
