}

fn report(counts: Kv) -> Result<Str, Str> {
  let keys = counts.keys("").map_err(|e| "cannot list counts")?;
  let mut rows: List<Row> = [];
  for k in keys {
    if k.starts_with("junk") { continue; }
    let v = counts.get(k).map_err(|e| "cannot read counts")?;
    if let Some(b) = v {
      rows.push(Row { page: k, total: b.to_str().parse_int().unwrap_or(0) });
    }
