  let mut todo: List<Rec> = [];
  let mut unchanged = 0;
  let ids = recs.keys();
  for id in ids {
    let rec = match recs.get(id) {
      Some(x) => x,
      None => continue,
    };
    let stored = stored_version(state, id)?;
    let need = match stored {
      None => true,
      Some(v) => rec.version > v,
    };
    if need {
      todo.push(rec);
    } else {
      statuses.insert(id, "unchanged");
      unchanged += 1;
    }
  }

  // Push each changed record.
  let mut synced = 0;
  let mut rejected = 0;
  let mut failed = 0;
  for rec in todo {
    let s = send_retry(api, "/records/" + rec.id, "application/json", rec.line.to_bytes());
    if s >= 200 && s < 300 {
      state.set("v/" + rec.id, rec.version.to_str().to_bytes()).map_err(|e| "state write failed")?;
      statuses.insert(rec.id, "synced");
      synced += 1;
    } else if s >= 400 && s < 500 {
      statuses.insert(rec.id, "rejected " + s.to_str());
      rejected += 1;
    } else {
      statuses.insert(rec.id, "failed");
      failed += 1;
    }
  }

  // One line per id, sorted by id, then the summary.
  for id in ids {
    if let Some(t) = statuses.get(id) {
      out.push(id + " " + t);
    }
  }
  out.push("synced " + synced.to_str() + " unchanged " + unchanged.to_str() + " rejected " + rejected.to_str() + " failed " + failed.to_str());
  Ok(out.join("\n"))
}

struct Rec { id: Str, version: Int, line: Str }

enum Outcome { Synced, Rejected(Int), Failed }

fn parse_rec(t: Str) -> Option<Rec> {
  let Ok(j) = t.parse_json() else { return None; };
  let Some(id) = j.get("id").and_then(|v| v.as_str()) else { return None; };
  let Some(version) = j.get("version").and_then(|v| v.as_int()) else { return None; };
  Some(Rec { id: id, version: version, line: t })
}

fn send_rec(api: Http, id: Str, line: Str) -> Outcome {
  let path = "/records/" + id;
  let mut attempt = 0;
  while attempt < 3 {
    attempt += 1;
    match api.send("PUT", path, ["content-type: application/json"], line.to_bytes(), 0) {
      Ok(r) => {
        if r.status >= 200 && r.status < 300 { return Outcome::Synced; }
        if r.status >= 500 && r.status < 600 { continue; }
        return Outcome::Rejected(r.status);
      }
      Err(_) => { continue; }
    }
  }
  Outcome::Failed
}

fn main(input: Dir, state: Kv, api: Http) -> Str {
  let Ok(bytes) = input.read("records.jsonl") else {
    return "error: cannot read records.jsonl";
  };
  let text = bytes.to_str();

  let mut recs: Map<Str, Rec> = Map::new();
  let mut out: List<Str> = [];
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let t = line.trim();
    if t == "" { continue; }
    match parse_rec(t) {
      Some(r) => { recs.insert(r.id, r); }
      None => { out.push("line " + n.to_str() + " invalid"); }
    }
  }

  let mut s = 0;
  let mut u = 0;
  let mut rj = 0;
  let mut f = 0;
  for id in recs.keys() {
    let Some(r) = recs.get(id) else { continue; };
    let Ok(prev) = state.get("v:" + id) else {
      return "error: state unreadable";
    };
    let last: Option<Int> = match prev {
      Some(b) => b.to_str().parse_int(),
      None => None,
    };
    let pushed = match last {
      Some(v) => r.version > v,
      None => true,
    };
    if !pushed {
      out.push(id + " unchanged");
      u += 1;
      continue;
    }
    match send_rec(api, id, r.line) {
      Outcome::Synced => {
        let Ok(_) = state.set("v:" + id, r.version.to_str().to_bytes()) else {
          return "error: state write failed";
        };
        out.push(id + " synced");
        s += 1;
      }
      Outcome::Rejected(st) => {
        out.push(id + " rejected " + st.to_str());
        rj += 1;
      }
      Outcome::Failed => {
        out.push(id + " failed");
        f += 1;
      }
    }
  }

  out.push("synced " + s.to_str() + " unchanged " + u.to_str() + " rejected " + rj.to_str() + " failed " + f.to_str());
  out.join("\n")
}

