fn main(input: Dir, state: Kv, api: Http) -> Result<Str, Str> {
  let text = match input.read("records.jsonl") {
    Ok(b) => b.to_str(),
    Err(_) => return Err("cannot read records.jsonl"),
  };

  let mut invalid: List<Str> = [];
  let mut recs: Map<Str, Rec> = Map::new();
  let lines = text.lines();
  for i in 0..lines.len() {
    let t = lines[i].trim();
    if t.len() == 0 { continue; }
    match parse_record(t) {
      Some(r) => { recs.insert(r.id, r); }
      None => { invalid.push("line " + (i + 1).to_str() + " invalid"); }
    }
  }

  let mut results: Map<Str, Str> = Map::new();
  let mut queue: List<Rec> = [];
  for id in recs.keys() {
    let Some(r) = recs.get(id) else { continue; };
    let prev: Option<Int> = match state.get("pushed:" + id) {
      Ok(Some(b)) => b.to_str().parse_int(),
      Ok(None) => None,
      Err(_) => return Err("state read failed"),
    };
    let should = match prev {
      Some(p) => r.version > p,
      None => true,
    };
    if should {
      queue.push(r);
    } else {
      results.insert(id, "unchanged");
    }
  }

  let mut round = 0;
  while queue.len() > 0 && round < 3 {
    round += 1;
    let mut reqs: List<HttpRequest> = [];
    for r in queue {
      reqs.push(HttpRequest {
        method: "PUT",
        path: "/records/" + r.id,
        headers: ["content-type: application/json"],
        body: r.line.to_bytes(),
        timeout_ms: 0,
      });
    }
    let answers = api.send_all(reqs);
    let mut next: List<Rec> = [];
    for i in 0..queue.len() {
      let r = queue[i];
      match answers[i] {
        Ok(resp) => {
          if resp.status >= 200 && resp.status < 300 {
            match state.set("pushed:" + r.id, r.version.to_str().to_bytes()) {
              Ok(_) => {}
              Err(_) => return Err("state write failed"),
            }
            results.insert(r.id, "synced");
          } else if resp.status >= 400 && resp.status < 500 {
            results.insert(r.id, "rejected " + resp.status.to_str());
          } else {
            next.push(r);
          }
        }
        Err(_) => { next.push(r); }
      }
    }
    queue = next;
  }
  for r in queue {
    results.insert(r.id, "failed");
  }

  let mut out: Str = "";
  for l in invalid {
    out = out + l + "\n";
  }

  let mut synced = 0;
  let mut unchanged = 0;
  let mut rejected = 0;
  let mut failed = 0;
  for id in results.keys() {
    let s = results.get(id).unwrap_or("failed");
    out = out + id + " " + s + "\n";
    if s == "synced" {
      synced += 1;
    } else if s == "unchanged" {
      unchanged += 1;
    } else if s.starts_with("rejected") {
      rejected += 1;
    } else {
      failed += 1;
    }
  }

  out = out + "synced " + synced.to_str() + " unchanged " + unchanged.to_str()
    + " rejected " + rejected.to_str() + " failed " + failed.to_str();
  Ok(out)
}

