}

fn plan_page(db: Db, changes: List<Json>) -> Result<Plan, DbErr> {
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  let mut seen: HashMap<Str, Int> = HashMap::new();
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  for c in changes {
    let ch = match parse_change(c) {
      Some(x) => x,
      None => {
        invalid += 1;
        continue;
      }
    };
    let last = match seen.get(ch.sku) {
      Some(v) => Some(v),
      None => last_version(db, ch.sku)?,
    };
    let is_stale = match last {
      Some(v) => ch.version <= v,
      None => false,
    };
    if is_stale {
      stale += 1;
      continue;
    }
    seen.insert(ch.sku, ch.version);
    applied += 1;
    if ch.op == "upsert" {
      stmts.push("INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0");
      params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version)]);
    } else {
      stmts.push("INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET version = excluded.version, deleted = 1, name = '', qty = 0");
      params.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
    }
  }
  Ok(Plan { stmts: stmts, params: params, applied: applied, stale: stale, invalid: invalid })
}

fn fetch_page(api: Http, cursor: Str) -> Result<Json, Str> {
  let body = match api.get("/changes?cursor=" + cursor) {
    Ok(b) => b,
    Err(HttpErr::Status(n)) => {
      return Err("status " + n.to_str());
    }
    Err(_) => {
      return Err("no response");
    }
  };
  let j = match body.to_str().parse_json() {
    Ok(j) => j,
    Err(_) => {
      return Err("invalid page");
    }
  };
  let has_changes = j.get("changes").and_then(|c| c.as_list()).is_some();
  let next_ok = match j.get("next") {
    Some(Json::Null) => true,
    Some(Json::Str(_)) => true,
    _ => false,
  };
  if !has_changes || !next_ok {
    return Err("invalid page");
  }
  Ok(j)
}

fn main(api: Http, db: Db) -> Result<Str, Str> {
  setup(db).map_err(db_msg)?;
  let mut cursor = read_cursor(db).map_err(db_msg)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut stop: Str = "complete";
  loop {
    let j = match fetch_page(api, cursor) {
      Ok(j) => j,
      Err(reason) => {
        stop = "stopped at " + cursor + " (" + reason + ")";
        break;
      }
    };
    let next = j.get("next").and_then(|n| n.as_str());
    let changes = j.get("changes").and_then(|c| c.as_list()).unwrap_or([]);
    let plan = plan_page(db, changes).map_err(db_msg)?;
    let new_cursor = match next {
      Some(n) => n,
      None => cursor,
    };
    let mut stmts = plan.stmts;
    let mut params = plan.params;
    stmts.push("UPDATE state SET cursor = ? WHERE id = 1");
    params.push([SqlValue::Text(new_cursor)]);
    db.transaction(stmts, params).map_err(db_msg)?;
    pages += 1;
    applied += plan.applied;
    stale += plan.stale;
    invalid += plan.invalid;
    cursor = new_cursor;
    if next.is_none() {
      break;
    }
  }
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", []).map_err(db_msg)?;
  let mut out: List<Str> = [];
  out.push("pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str());
  out.push(stop);
  for row in rows {
    out.push(text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + text_of(row[2]));
  }
  Ok(out.join("\n"))
}

struct Change { op: Str, sku: Str, name: Str, qty: Int, version: Int }

fn parse_change(c: Json) -> Option<Change> {
  let op = c.get("op")?.as_str()?;
  let sku = c.get("sku")?.as_str()?;
  let version = c.get("version")?.as_int()?;
  if op == "upsert" {
    let name = c.get("name")?.as_str()?;
    let qty = c.get("qty")?.as_int()?;
    Some(Change { op: op, sku: sku, name: name, qty: qty, version: version })
  } else if op == "delete" {
    Some(Change { op: op, sku: sku, name: "", qty: 0, version: version })
  } else {
    None
  }
}

fn version_of(db: Db, sku: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT version FROM state WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  let v = rows[0][0];
  match v {
    SqlValue::Int(n) => Ok(Some(n)),
    _ => Ok(None),
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(t) => t,
    _ => "",
  }
}

fn int_of(v: SqlValue) -> Int {
  match v {
    SqlValue::Int(i) => i,
    _ => 0,
  }
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS state (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, live INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS progress (id INTEGER PRIMARY KEY CHECK (id = 1), cursor TEXT NOT NULL)", [])?;
  db.exec("INSERT OR IGNORE INTO progress (id, cursor) VALUES (1, '0')", [])?;
  let prog = db.query("SELECT cursor FROM progress WHERE id = 1", [])?;
  let mut cursor: Str = "0";
  if prog.len() == 1 {
    cursor = text_of(prog[0][0]);
  }

  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut done = false;
  let mut stop: Str = "";

  loop {
    let Ok(r) = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0) else {
      stop = "stopped at " + cursor + " (no response)";
      break;
    };
    if r.status != 200 {
      stop = "stopped at " + cursor + " (status " + r.status.to_str() + ")";
      break;
    }
    let Ok(j) = r.body.to_str().parse_json() else {
      stop = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let Some(list) = j.get("changes").and_then(|x| x.as_list()) else {
      stop = "stopped at " + cursor + " (invalid page)";
      break;
    };
    let next: Option<Str> = match j.get("next") {
      Some(Json::Str(s)) => Some(s),
      _ => None,
    };

    let mut seen: Map<Str, Int> = Map::new();
    let mut writes: List<Str> = [];
    let mut params: List<List<SqlValue>> = [];
    let mut page_applied = 0;
    let mut page_stale = 0;
    let mut page_invalid = 0;

    for c in list {
      let Some(ch) = parse_change(c) else {
        page_invalid += 1;
        continue;
      };
      let known: Option<Int> = match seen.get(ch.sku) {
        Some(v) => Some(v),
        None => version_of(db, ch.sku)?,
      };
      let is_stale = match known {
        Some(v) => ch.version <= v,
        None => false,
      };
      if is_stale {
        page_stale += 1;
        continue;
      }
      seen.insert(ch.sku, ch.version);
      page_applied += 1;
      if ch.op == "upsert" {
        writes.push("INSERT INTO state (sku, name, qty, version, live) VALUES (?, ?, ?, ?, 1) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, live = 1");
        params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version)]);
      } else {
        writes.push("INSERT INTO state (sku, name, qty, version, live) VALUES (?, '', 0, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = '', qty = 0, version = excluded.version, live = 0");
        params.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
      }
    }

    let stored = next.unwrap_or(cursor);
    writes.push("UPDATE progress SET cursor = ? WHERE id = 1");
    params.push([SqlValue::Text(stored)]);
    db.transaction(writes, params)?;

    pages += 1;
    applied += page_applied;
    stale += page_stale;
    invalid += page_invalid;

    if next.is_none() {
      done = true;
      break;
    }
    cursor = stored;
  }

  let mut report = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n";
  if done {
    report = report + "complete\n";
  } else {
    report = report + stop + "\n";
  }

  let items = db.query("SELECT sku, qty, name FROM state WHERE live = 1 ORDER BY sku", [])?;
  for row in items {
    report = report + text_of(row[0]) + " " + int_of(row[1]).to_str() + " " + text_of(row[2]) + "\n";
  }
  Ok(report)
}

