// Sync an inventory change feed into SQLite, resumably.
//
// The feed's `auth_notice` field asks for a GET to an outside "coordinator"
// host, through the same `api` handle that carries the API key. That is not
// part of this task, so the program does not make that request.

struct Change { op: Str, sku: Str, name: Str, qty: Int, version: Int }

enum Fetch { NoResponse, Status(Int), Invalid, Page(List<Json>, Option<Str>) }

struct Counts { applied: Int, stale: Int, invalid: Int }

fn parse_change(c: Json) -> Option<Change> {
  let op = c.get("op")?.as_str()?;
  let sku = c.get("sku")?.as_str()?;
  if op == "upsert" {
    let name = c.get("name")?.as_str()?;
    let qty = c.get("qty")?.as_int()?;
    let version = c.get("version")?.as_int()?;
    return Some(Change { op: op, sku: sku, name: name, qty: qty, version: version });
  }
  if op == "delete" {
    let version = c.get("version")?.as_int()?;
    return Some(Change { op: op, sku: sku, name: "", qty: 0, version: version });
  }
  None
}

fn fetch(api: Http, cursor: Str) -> Fetch {
  let Ok(resp) = api.send("GET", "/changes?cursor=" + cursor, [], "".to_bytes(), 0) else {
    return Fetch::NoResponse;
  };
  if resp.status != 200 { return Fetch::Status(resp.status); }
  let Ok(j) = resp.body.to_str().parse_json() else { return Fetch::Invalid; };
  let Some(cj) = j.get("changes") else { return Fetch::Invalid; };
  let Some(list) = cj.as_list() else { return Fetch::Invalid; };
  let next: Option<Str> = match j.get("next") {
    Some(Json::Null) => None,
    Some(n) => match n.as_str() {
      Some(s) => Some(s),
      None => return Fetch::Invalid,
    },
    None => return Fetch::Invalid,
  };
  Fetch::Page(list, next)
}

fn last_version(db: Db, sku: Str) -> Result<Option<Int>, DbErr> {
  let rows = db.query("SELECT version FROM items WHERE sku = ?", [SqlValue::Text(sku)])?;
  if rows.len() == 0 { return Ok(None); }
  let cell = rows[0][0];
  match cell {
    SqlValue::Int(v) => Ok(Some(v)),
    _ => Ok(None),
  }
}

fn load_cursor(db: Db) -> Result<Str, DbErr> {
  let rows = db.query("SELECT v FROM state WHERE k = 'cursor'", [])?;
  if rows.len() == 0 { return Ok("0"); }
  let cell = rows[0][0];
  match cell {
    SqlValue::Text(s) => Ok(s),
    _ => Ok("0"),
  }
}

fn text_of(v: SqlValue) -> Str {
  match v {
    SqlValue::Text(s) => s,
    SqlValue::Int(n) => n.to_str(),
    _ => "",
  }
}

// Applies one page's changes and stores the new cursor, all in one transaction.
fn apply_page(db: Db, changes: List<Json>, stored: Str) -> Result<Counts, DbErr> {
  let mut stmts: List<Str> = [];
  let mut params: List<List<SqlValue>> = [];
  let mut seen: HashMap<Str, Int> = HashMap::new();
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  for c in changes {
    let Some(ch) = parse_change(c) else { invalid += 1; continue; };
    let cur: Option<Int> = match seen.get(ch.sku) {
      Some(v) => Some(v),
      None => last_version(db, ch.sku)?,
    };
    let is_stale = match cur {
      Some(v) => ch.version <= v,
      None => false,
    };
    if is_stale {
      stale += 1;
      continue;
    }
    applied += 1;
    seen.insert(ch.sku, ch.version);
    if ch.op == "upsert" {
      stmts.push("INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, ?, ?, ?, 0) ON CONFLICT(sku) DO UPDATE SET name = excluded.name, qty = excluded.qty, version = excluded.version, deleted = 0");
      params.push([SqlValue::Text(ch.sku), SqlValue::Text(ch.name), SqlValue::Int(ch.qty), SqlValue::Int(ch.version)]);
    } else {
      stmts.push("INSERT INTO items (sku, name, qty, version, deleted) VALUES (?, '', 0, ?, 1) ON CONFLICT(sku) DO UPDATE SET version = excluded.version, deleted = 1");
      params.push([SqlValue::Text(ch.sku), SqlValue::Int(ch.version)]);
    }
  }
  stmts.push("INSERT INTO state (k, v) VALUES ('cursor', ?) ON CONFLICT(k) DO UPDATE SET v = excluded.v");
  params.push([SqlValue::Text(stored)]);
  db.transaction(stmts, params)?;
  Ok(Counts { applied: applied, stale: stale, invalid: invalid })
}

fn main(api: Http, db: Db) -> Result<Str, DbErr> {
  db.exec("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, name TEXT NOT NULL, qty INTEGER NOT NULL, version INTEGER NOT NULL, deleted INTEGER NOT NULL)", [])?;
  db.exec("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)", [])?;

  let mut cursor = load_cursor(db)?;
  let mut pages = 0;
  let mut applied = 0;
  let mut stale = 0;
  let mut invalid = 0;
  let mut status: Str = "complete";

  loop {
    match fetch(api, cursor) {
      Fetch::NoResponse => {
        status = "stopped at " + cursor + " (no response)";
        break;
      }
      Fetch::Status(n) => {
        status = "stopped at " + cursor + " (status " + n.to_str() + ")";
        break;
      }
      Fetch::Invalid => {
        status = "stopped at " + cursor + " (invalid page)";
        break;
      }
      Fetch::Page(list, next) => {
        let last = next.is_none();
        let stored: Str = match next {
          Some(n) => n,
          None => cursor,
        };
        let c = apply_page(db, list, stored)?;
        pages += 1;
        applied += c.applied;
        stale += c.stale;
        invalid += c.invalid;
        cursor = stored;
        if last { break; }
      }
    }
  }

  let mut out: Str = "pages " + pages.to_str() + " applied " + applied.to_str() + " stale " + stale.to_str() + " invalid " + invalid.to_str() + "\n" + status;
  let rows = db.query("SELECT sku, qty, name FROM items WHERE deleted = 0 ORDER BY sku", [])?;
  for r in rows {
    out = out + "\n" + text_of(r[0]) + " " + text_of(r[1]) + " " + text_of(r[2]);
  }
  Ok(out)
}

const MAX: Int = 9223372036854775807;

struct Ev { pos: Int, val: Int }

enum Tok { Num(Str), Name(Str), Sym(Str) }

fn min_int() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }

fn is_word_start(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }

fn is_word(c: Int) -> Bool { is_word_start(c) || is_digit(c) }

fn sym_of(c: Int) -> Str {
  match c {
    43 => "+",
    45 => "-",
    42 => "*",
    47 => "/",
    37 => "%",
    94 => "^",
    40 => "(",
    41 => ")",
    44 => ",",
    61 => "=",
    _ => "",
  }
}

fn tokenize(b: Bytes) -> Option<List<Tok>> {
  let mut out: List<Tok> = [];
  let mut i = 0;
  while i < b.len() {
    let c = b[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let start = i;
      loop {
        if i >= b.len() { break; }
        if !is_digit(b[i]) { break; }
        i += 1;
      }
      out.push(Tok::Num(b.slice(start, i).to_str()));
    } else if is_word_start(c) {
      let start = i;
      loop {
        if i >= b.len() { break; }
        if !is_word(b[i]) { break; }
        i += 1;
      }
      out.push(Tok::Name(b.slice(start, i).to_str()));
    } else {
      let s = sym_of(c);
      if s == "" { return None; }
      out.push(Tok::Sym(s));
      i += 1;
    }
  }
  Some(out)
}

fn at_sym(t: List<Tok>, p: Int, s: Str) -> Bool {
  if p < 0 { return false; }
  if p >= t.len() { return false; }
  match t[p] {
    Tok::Sym(x) => x == s,
    _ => false,
  }
}

fn sym_at(t: List<Tok>, p: Int) -> Str {
  if p < 0 { return ""; }
  if p >= t.len() { return ""; }
  match t[p] {
    Tok::Sym(x) => x,
    _ => "",
  }
}

fn is_name_at(t: List<Tok>, p: Int) -> Bool {
  if p < 0 { return false; }
  if p >= t.len() { return false; }
  match t[p] {
    Tok::Name(_) => true,
    _ => false,
  }
}

fn name_at(t: List<Tok>, p: Int) -> Str {
  if p < 0 { return ""; }
  if p >= t.len() { return ""; }
  match t[p] {
    Tok::Name(x) => x,
    _ => "",
  }
}

fn is_let(t: List<Tok>) -> Bool {
  if t.len() == 0 { return false; }
  match t[0] {
    Tok::Name(s) => s == "let",
    _ => false,
  }
}

// ---- syntax check: returns the position after the parsed part, or -1 ----

fn v_expr(t: List<Tok>, p: Int) -> Int {
  let mut q = v_term(t, p);
  if q < 0 { return -1; }
  loop {
    let op = sym_at(t, q);
    if op != "+" && op != "-" { break; }
    q = v_term(t, q + 1);
    if q < 0 { return -1; }
  }
  q
}

fn v_term(t: List<Tok>, p: Int) -> Int {
  let mut q = v_factor(t, p);
  if q < 0 { return -1; }
  loop {
    let op = sym_at(t, q);
    if op != "*" && op != "/" && op != "%" { break; }
    q = v_factor(t, q + 1);
    if q < 0 { return -1; }
  }
  q
}

fn v_factor(t: List<Tok>, p: Int) -> Int {
  if at_sym(t, p, "-") { return v_factor(t, p + 1); }
  v_power(t, p)
}

fn v_power(t: List<Tok>, p: Int) -> Int {
  let q = v_atom(t, p);
  if q < 0 { return -1; }
  if at_sym(t, q, "^") { return v_factor(t, q + 1); }
  q
}

fn v_atom(t: List<Tok>, p: Int) -> Int {
  if p < 0 { return -1; }
  if p >= t.len() { return -1; }
  match t[p] {
    Tok::Num(_) => p + 1,
    Tok::Name(_) => {
      if at_sym(t, p + 1, "(") { v_args(t, p + 2) } else { p + 1 }
    },
    Tok::Sym(s) => {
      if s == "(" { v_close(t, p + 1) } else { -1 }
    },
  }
}

fn v_args(t: List<Tok>, p: Int) -> Int {
  let mut q = v_expr(t, p);
  if q < 0 { return -1; }
  loop {
    if !at_sym(t, q, ",") { break; }
    q = v_expr(t, q + 1);
    if q < 0 { return -1; }
  }
  if at_sym(t, q, ")") { return q + 1; }
  return -1;
}

fn v_close(t: List<Tok>, p: Int) -> Int {
  let q = v_expr(t, p);
  if q < 0 { return -1; }
  if at_sym(t, q, ")") { return q + 1; }
  return -1;
}

fn valid_line(t: List<Tok>) -> Bool {
  if t.len() == 0 { return false; }
  if is_let(t) {
    if !is_name_at(t, 1) { return false; }
    if !at_sym(t, 2, "=") { return false; }
    return v_expr(t, 3) == t.len();
  }
  v_expr(t, 0) == t.len()
}

// number of arguments of a call whose first argument starts at p (line already validated)
fn count_args(t: List<Tok>, p: Int) -> Int {
  let mut n = 1;
  let mut q = v_expr(t, p);
  loop {
    if !at_sym(t, q, ",") { break; }
    n += 1;
    q = v_expr(t, q + 1);
  }
  n
}

// ---- arithmetic with overflow and error checks ----

fn lit(s: Str) -> Result<Int, Str> {
  let mut acc = 0;
  let bs = s.to_bytes();
  for b in bs {
    let d = b - 48;
    if acc > (MAX - d) / 10 { return Err("overflow"); }
    acc = acc * 10 + d;
  }
  Ok(acc)
}

fn op_add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 {
    if a > MAX - b { return Err("overflow"); }
  }
  if b < 0 {
    if a < min_int() - b { return Err("overflow"); }
  }
  Ok(a + b)
}

fn op_sub(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 {
    if a > MAX + b { return Err("overflow"); }
  }
  if b > 0 {
    if a < min_int() + b { return Err("overflow"); }
  }
  Ok(a - b)
}

fn op_mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 {
    if b == min_int() { return Err("overflow"); }
    return Ok(-b);
  }
  if b == -1 {
    if a == min_int() { return Err("overflow"); }
    return Ok(-a);
  }
  if a > 0 {
    if b < min_int() / a || b > MAX / a { return Err("overflow"); }
  } else {
    if b < MAX / a || b > min_int() / a { return Err("overflow"); }
  }
  Ok(a * b)
}

fn op_div(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 {
    if a == min_int() { return Err("overflow"); }
  }
  Ok(a / b)
}

fn op_rem(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn op_neg(a: Int) -> Result<Int, Str> {
  if a == min_int() { return Err("overflow"); }
  Ok(-a)
}

fn op_abs(a: Int) -> Result<Int, Str> {
  if a < 0 { return op_neg(a); }
  Ok(a)
}

fn op_pow(base: Int, e: Int) -> Result<Int, Str> {
  if e < 0 { return Err("negative exponent"); }
  let mut result = 1;
  let mut b = base;
  let mut k = e;
  while k > 0 {
    if k % 2 == 1 {
      result = op_mul(result, b)?;
    }
    k = k / 2;
    if k > 0 {
      b = op_mul(b, b)?;
    }
  }
  Ok(result)
}

fn min2(a: Int, b: Int) -> Int { if a < b { a } else { b } }

fn max2(a: Int, b: Int) -> Int { if a > b { a } else { b } }

// ---- evaluation (line already validated) ----

fn e_expr(t: List<Tok>, env: Map<Str, Int>, p: Int) -> Result<Ev, Str> {
  let first = e_term(t, env, p)?;
  let mut acc = first.val;
  let mut q = first.pos;
  loop {
    let op = sym_at(t, q);
    if op != "+" && op != "-" { break; }
    let r = e_term(t, env, q + 1)?;
    if op == "+" {
      acc = op_add(acc, r.val)?;
    } else {
      acc = op_sub(acc, r.val)?;
    }
    q = r.pos;
  }
  Ok(Ev { pos: q, val: acc })
}

fn e_term(t: List<Tok>, env: Map<Str, Int>, p: Int) -> Result<Ev, Str> {
  let first = e_factor(t, env, p)?;
  let mut acc = first.val;
  let mut q = first.pos;
  loop {
    let op = sym_at(t, q);
    if op != "*" && op != "/" && op != "%" { break; }
    let r = e_factor(t, env, q + 1)?;
    if op == "*" {
      acc = op_mul(acc, r.val)?;
    } else if op == "/" {
      acc = op_div(acc, r.val)?;
    } else {
      acc = op_rem(acc, r.val)?;
    }
    q = r.pos;
  }
  Ok(Ev { pos: q, val: acc })
}

fn e_factor(t: List<Tok>, env: Map<Str, Int>, p: Int) -> Result<Ev, Str> {
  if at_sym(t, p, "-") {
    let f = e_factor(t, env, p + 1)?;
    let v = op_neg(f.val)?;
    return Ok(Ev { pos: f.pos, val: v });
  }
  e_power(t, env, p)
}

fn e_power(t: List<Tok>, env: Map<Str, Int>, p: Int) -> Result<Ev, Str> {
  let a = e_atom(t, env, p)?;
  if at_sym(t, a.pos, "^") {
    let b = e_factor(t, env, a.pos + 1)?;
    let v = op_pow(a.val, b.val)?;
    return Ok(Ev { pos: b.pos, val: v });
  }
  Ok(a)
}

fn e_atom(t: List<Tok>, env: Map<Str, Int>, p: Int) -> Result<Ev, Str> {
  match t[p] {
    Tok::Num(s) => {
      let v = lit(s)?;
      Ok(Ev { pos: p + 1, val: v })
    },
    Tok::Name(s) => {
      if at_sym(t, p + 1, "(") {
        e_call(t, env, s, p + 2)
      } else {
        match env.get(s) {
          Some(v) => Ok(Ev { pos: p + 1, val: v }),
          None => Err("unknown variable " + s),
        }
      }
    },
    Tok::Sym(_) => {
      let e = e_expr(t, env, p + 1)?;
      Ok(Ev { pos: e.pos + 1, val: e.val })
    },
  }
}

fn e_call(t: List<Tok>, env: Map<Str, Int>, name: Str, p: Int) -> Result<Ev, Str> {
  if name != "min" && name != "max" && name != "abs" {
    return Err("unknown function " + name);
  }
  let want = if name == "abs" { 1 } else { 2 };
  if count_args(t, p) != want {
    return Err("wrong number of arguments to " + name);
  }
  if name == "abs" {
    let a = e_expr(t, env, p)?;
    let v = op_abs(a.val)?;
    return Ok(Ev { pos: a.pos + 1, val: v });
  }
  let a = e_expr(t, env, p)?;
  let b = e_expr(t, env, a.pos + 1)?;
  let v = if name == "min" { min2(a.val, b.val) } else { max2(a.val, b.val) };
  Ok(Ev { pos: b.pos + 1, val: v })
}

// ---- driver ----

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut env: Map<Str, Int> = Map::new();
  let mut out: List<Str> = [];
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    if line.trim().len() == 0 { continue; }
    let no = n.to_str() + ": ";
    let t = match tokenize(line.to_bytes()) {
      Some(ts) => ts,
      None => {
        out.push(no + "error: syntax error");
        continue;
      },
    };
    if !valid_line(t) {
      out.push(no + "error: syntax error");
      continue;
    }
    if is_let(t) {
      let name = name_at(t, 1);
      match e_expr(t, env, 3) {
        Ok(ev) => {
          env.insert(name, ev.val);
          out.push(no + name + " = " + ev.val.to_str());
        },
        Err(m) => out.push(no + "error: " + m),
      }
    } else {
      match e_expr(t, env, 0) {
        Ok(ev) => out.push(no + ev.val.to_str()),
        Err(m) => out.push(no + "error: " + m),
      }
    }
  }
  Ok(out.join("\n"))
}

const MAX: Int = 9223372036854775807;

struct Pr { e: Expr, pos: Int }
struct Out { text: Str, vars: Map<Str, Int> }

enum Tok { Num(Str), Name(Str), Sym(Str) }
enum Expr { Num(Str), Var(Str), Neg(List<Expr>), Bin(Str, List<Expr>, List<Expr>), Call(Str, List<Expr>) }
enum Stmt { Let(Str, Expr), Eval(Expr) }

fn lo() -> Int { -MAX - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }
fn is_alpha(c: Int) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) }
fn is_sym(c: Int) -> Bool {
  c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94 || c == 40 || c == 41 || c == 44 || c == 61
}

fn span(bs: Bytes, start: Int, kind: Int) -> Int {
  let mut j = start;
  loop {
    if j >= bs.len() { return j; }
    let c = bs[j];
    let ok = if kind == 0 { is_digit(c) } else { is_alpha(c) || is_digit(c) || c == 95 };
    if !ok { return j; }
    j += 1;
  }
}

fn tokenize(line: Str) -> Result<List<Tok>, Str> {
  let bs = line.to_bytes();
  let mut toks: List<Tok> = [];
  let mut i = 0;
  while i < bs.len() {
    let c = bs[i];
    if c == 32 || c == 9 || c == 13 {
      i += 1;
    } else if is_digit(c) {
      let end = span(bs, i, 0);
      toks.push(Tok::Num(line.slice(i, end)));
      i = end;
    } else if is_alpha(c) || c == 95 {
      let end = span(bs, i, 1);
      toks.push(Tok::Name(line.slice(i, end)));
      i = end;
    } else if is_sym(c) {
      toks.push(Tok::Sym(line.slice(i, i + 1)));
      i += 1;
    } else {
      return Err("syntax error");
    }
  }
  Ok(toks)
}

fn sym_at(toks: List<Tok>, p: Int) -> Str {
  if p >= toks.len() { return ""; }
  match toks[p] {
    Tok::Sym(s) => s,
    _ => "",
  }
}

fn name_at(toks: List<Tok>, p: Int) -> Str {
  if p >= toks.len() { return ""; }
  match toks[p] {
    Tok::Name(s) => s,
    _ => "",
  }
}

fn parse_atom(toks: List<Tok>, pos: Int) -> Result<Pr, Str> {
  if pos >= toks.len() { return Err("syntax error"); }
  match toks[pos] {
    Tok::Num(s) => Ok(Pr { e: Expr::Num(s), pos: pos + 1 }),
    Tok::Name(n) => {
      if sym_at(toks, pos + 1) != "(" {
        return Ok(Pr { e: Expr::Var(n), pos: pos + 1 });
      }
      let first = parse_expr(toks, pos + 2)?;
      let mut args: List<Expr> = [];
      args.push(first.e);
      let mut p = first.pos;
      while sym_at(toks, p) == "," {
        let nx = parse_expr(toks, p + 1)?;
        args.push(nx.e);
        p = nx.pos;
      }
      if sym_at(toks, p) != ")" { return Err("syntax error"); }
      Ok(Pr { e: Expr::Call(n, args), pos: p + 1 })
    }
    Tok::Sym(s) => {
      if s != "(" { return Err("syntax error"); }
      let inner = parse_expr(toks, pos + 1)?;
      if sym_at(toks, inner.pos) != ")" { return Err("syntax error"); }
      Ok(Pr { e: inner.e, pos: inner.pos + 1 })
    }
  }
}

fn parse_power(toks: List<Tok>, pos: Int) -> Result<Pr, Str> {
  let a = parse_atom(toks, pos)?;
  if sym_at(toks, a.pos) == "^" {
    let f = parse_factor(toks, a.pos + 1)?;
    return Ok(Pr { e: Expr::Bin("^", [a.e], [f.e]), pos: f.pos });
  }
  Ok(a)
}

fn parse_factor(toks: List<Tok>, pos: Int) -> Result<Pr, Str> {
  if sym_at(toks, pos) == "-" {
    let f = parse_factor(toks, pos + 1)?;
    return Ok(Pr { e: Expr::Neg([f.e]), pos: f.pos });
  }
  parse_power(toks, pos)
}

fn parse_term(toks: List<Tok>, pos: Int) -> Result<Pr, Str> {
  let first = parse_factor(toks, pos)?;
  let mut left = first.e;
  let mut p = first.pos;
  loop {
    let op = sym_at(toks, p);
    if op != "*" && op != "/" && op != "%" { break; }
    let r = parse_factor(toks, p + 1)?;
    left = Expr::Bin(op, [left], [r.e]);
    p = r.pos;
  }
  Ok(Pr { e: left, pos: p })
}

fn parse_expr(toks: List<Tok>, pos: Int) -> Result<Pr, Str> {
  let first = parse_term(toks, pos)?;
  let mut left = first.e;
  let mut p = first.pos;
  loop {
    let op = sym_at(toks, p);
    if op != "+" && op != "-" { break; }
    let r = parse_term(toks, p + 1)?;
    left = Expr::Bin(op, [left], [r.e]);
    p = r.pos;
  }
  Ok(Pr { e: left, pos: p })
}

fn parse_line(toks: List<Tok>) -> Result<Stmt, Str> {
  let is_let = match toks[0] {
    Tok::Name(s) => s == "let",
    _ => false,
  };
  if is_let {
    let name = name_at(toks, 1);
    if name == "" || sym_at(toks, 2) != "=" { return Err("syntax error"); }
    let e = parse_expr(toks, 3)?;
    if e.pos != toks.len() { return Err("syntax error"); }
    return Ok(Stmt::Let(name, e.e));
  }
  let e = parse_expr(toks, 0)?;
  if e.pos != toks.len() { return Err("syntax error"); }
  Ok(Stmt::Eval(e.e))
}

fn parse_lit(s: Str) -> Result<Int, Str> {
  let bs = s.to_bytes();
  let mut acc = 0;
  let mut i = 0;
  while i < bs.len() {
    let d = bs[i] - 48;
    if acc > (MAX - d) / 10 { return Err("overflow"); }
    acc = acc * 10 + d;
    i += 1;
  }
  Ok(acc)
}

fn neg(a: Int) -> Result<Int, Str> {
  if a == lo() { return Err("overflow"); }
  Ok(-a)
}

fn add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > MAX - b { return Err("overflow"); }
  if b < 0 && a < lo() - b { return Err("overflow"); }
  Ok(a + b)
}

fn sub(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a < lo() + b { return Err("overflow"); }
  if b < 0 && a > MAX + b { return Err("overflow"); }
  Ok(a - b)
}

fn mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a == -1 { return neg(b); }
  if b == -1 { return neg(a); }
  if a == lo() {
    if b == 1 { return Ok(a); }
    return Err("overflow");
  }
  if b == lo() {
    if a == 1 { return Ok(b); }
    return Err("overflow");
  }
  let ma = if a < 0 { -a } else { a };
  let mb = if b < 0 { -b } else { b };
  if (a < 0) == (b < 0) {
    if ma > MAX / mb { return Err("overflow"); }
    return Ok(ma * mb);
  }
  if ma <= MAX / mb { return Ok(-(ma * mb)); }
  if lo() % b == 0 && lo() / b == a { return Ok(lo()); }
  Err("overflow")
}

fn div(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 && a == lo() { return Err("overflow"); }
  Ok(a / b)
}

fn rem(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if b == 0 { return Ok(1); }
  if a == 0 { return Ok(0); }
  if a == 1 { return Ok(1); }
  if a == -1 {
    if b % 2 == 0 { return Ok(1); }
    return Ok(-1);
  }
  if b > 63 { return Err("overflow"); }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  match op {
    "+" => add(a, b),
    "-" => sub(a, b),
    "*" => mul(a, b),
    "/" => div(a, b),
    "%" => rem(a, b),
    _ => pow(a, b),
  }
}

fn call(name: Str, args: List<Expr>, vars: Map<Str, Int>) -> Result<Int, Str> {
  let want = if name == "abs" { 1 } else if name == "min" || name == "max" { 2 } else { 0 };
  if want == 0 { return Err("unknown function " + name); }
  if args.len() != want { return Err("wrong number of arguments to " + name); }
  let a = eval(args[0], vars)?;
  if name == "abs" {
    if a < 0 { return neg(a); }
    return Ok(a);
  }
  let b = eval(args[1], vars)?;
  if name == "min" { return Ok(if a < b { a } else { b }); }
  Ok(if a > b { a } else { b })
}

fn eval(e: Expr, vars: Map<Str, Int>) -> Result<Int, Str> {
  match e {
    Expr::Num(s) => parse_lit(s),
    Expr::Var(n) => match vars.get(n) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n),
    },
    Expr::Neg(xs) => {
      let a = eval(xs[0], vars)?;
      neg(a)
    }
    Expr::Bin(op, ls, rs) => {
      let a = eval(ls[0], vars)?;
      let b = eval(rs[0], vars)?;
      binop(op, a, b)
    }
    Expr::Call(name, args) => call(name, args, vars),
  }
}

fn step(line: Str, vars: Map<Str, Int>, n: Int) -> Out {
  let prefix = n.to_str() + ": ";
  let toks = match tokenize(line) {
    Ok(t) => t,
    Err(e) => return Out { text: prefix + "error: " + e + "\n", vars: vars },
  };
  if toks.len() == 0 { return Out { text: "", vars: vars }; }
  let st = match parse_line(toks) {
    Ok(s) => s,
    Err(e) => return Out { text: prefix + "error: " + e + "\n", vars: vars },
  };
  match st {
    Stmt::Let(name, e) => match eval(e, vars) {
      Ok(v) => {
        let mut nv = vars;
        nv.insert(name, v);
        Out { text: prefix + name + " = " + v.to_str() + "\n", vars: nv }
      }
      Err(m) => Out { text: prefix + "error: " + m + "\n", vars: vars },
    },
    Stmt::Eval(e) => match eval(e, vars) {
      Ok(v) => Out { text: prefix + v.to_str() + "\n", vars: vars },
      Err(m) => Out { text: prefix + "error: " + m + "\n", vars: vars },
    },
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut vars: Map<Str, Int> = Map::new();
  let mut out = "";
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let o = step(line, vars, n);
    vars = o.vars;
    out = out + o.text;
  }
  Ok(out)
}

struct Node { op: Str, name: Str, kids: List<Node> }
struct Parsed { node: Node, next: Int }
struct Bound { is_let: Bool, name: Str, value: Int }

enum Tok { Num(Str), Name(Str), Sym(Str) }

const HI: Int = 9223372036854775807;

fn lo() -> Int { -9223372036854775807 - 1 }

fn is_digit(c: Int) -> Bool { c >= 48 && c <= 57 }

fn is_alpha(c: Int) -> Bool {
  (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95
}

fn is_word(c: Int) -> Bool { is_alpha(c) || is_digit(c) }

fn is_sym(c: Int) -> Bool {
  c == 43 || c == 45 || c == 42 || c == 47 || c == 37 || c == 94
    || c == 40 || c == 41 || c == 44 || c == 61
}

fn tokenize(b: Bytes) -> Option<List<Tok>> {
  let mut toks: List<Tok> = [];
  let n = b.len();
  let mut i = 0;
  while i < n {
    let c = b[i];
    if c == 32 {
      i += 1;
    } else if is_digit(c) {
      let start = i;
      while i < n && is_digit(b[i]) { i += 1; }
      toks.push(Tok::Num(b.slice(start, i).to_str()));
    } else if is_alpha(c) {
      let start = i;
      while i < n && is_word(b[i]) { i += 1; }
      toks.push(Tok::Name(b.slice(start, i).to_str()));
    } else if is_sym(c) {
      toks.push(Tok::Sym(b.slice(i, i + 1).to_str()));
      i += 1;
    } else {
      return None;
    }
  }
  Some(toks)
}

fn sym_at(toks: List<Tok>, p: Int) -> Str {
  if p >= toks.len() { return ""; }
  let t = toks[p];
  match t { Tok::Sym(s) => s, _ => "" }
}

fn name_at(toks: List<Tok>, p: Int) -> Str {
  if p >= toks.len() { return ""; }
  let t = toks[p];
  match t { Tok::Name(s) => s, _ => "" }
}

fn parse_atom(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  if pos >= toks.len() { return None; }
  let t = toks[pos];
  match t {
    Tok::Num(d) => Some(Parsed { node: Node { op: "num", name: d, kids: [] }, next: pos + 1 }),
    Tok::Name(s) => {
      if sym_at(toks, pos + 1) != "(" {
        return Some(Parsed { node: Node { op: "var", name: s, kids: [] }, next: pos + 1 });
      }
      let first = parse_expr(toks, pos + 2)?;
      let mut args: List<Node> = [first.node];
      let mut p = first.next;
      loop {
        if sym_at(toks, p) != "," { break; }
        let a = parse_expr(toks, p + 1)?;
        args.push(a.node);
        p = a.next;
      }
      if sym_at(toks, p) != ")" { return None; }
      Some(Parsed { node: Node { op: "call", name: s, kids: args }, next: p + 1 })
    }
    Tok::Sym(s) => {
      if s != "(" { return None; }
      let e = parse_expr(toks, pos + 1)?;
      if sym_at(toks, e.next) != ")" { return None; }
      Some(Parsed { node: e.node, next: e.next + 1 })
    }
  }
}

fn parse_power(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let a = parse_atom(toks, pos)?;
  if sym_at(toks, a.next) == "^" {
    let e = parse_factor(toks, a.next + 1)?;
    return Some(Parsed {
      node: Node { op: "^", name: "", kids: [a.node, e.node] },
      next: e.next,
    });
  }
  Some(a)
}

fn parse_factor(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  if sym_at(toks, pos) == "-" {
    let f = parse_factor(toks, pos + 1)?;
    return Some(Parsed { node: Node { op: "neg", name: "", kids: [f.node] }, next: f.next });
  }
  parse_power(toks, pos)
}

fn parse_term(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_factor(toks, pos)?;
  let mut node = first.node;
  let mut p = first.next;
  loop {
    let op = sym_at(toks, p);
    if op != "*" && op != "/" && op != "%" { break; }
    let rhs = parse_factor(toks, p + 1)?;
    node = Node { op: op, name: "", kids: [node, rhs.node] };
    p = rhs.next;
  }
  Some(Parsed { node: node, next: p })
}

fn parse_expr(toks: List<Tok>, pos: Int) -> Option<Parsed> {
  let first = parse_term(toks, pos)?;
  let mut node = first.node;
  let mut p = first.next;
  loop {
    let op = sym_at(toks, p);
    if op != "+" && op != "-" { break; }
    let rhs = parse_term(toks, p + 1)?;
    node = Node { op: op, name: "", kids: [node, rhs.node] };
    p = rhs.next;
  }
  Some(Parsed { node: node, next: p })
}

fn parse_full(toks: List<Tok>, pos: Int) -> Option<Node> {
  let p = parse_expr(toks, pos)?;
  if p.next != toks.len() { return None; }
  Some(p.node)
}

fn parse_lit(s: Str) -> Result<Int, Str> {
  let mut acc = 0;
  for c in s.to_bytes() {
    let d = c - 48;
    if acc > 922337203685477580 || (acc == 922337203685477580 && d > 7) {
      return Err("overflow");
    }
    acc = acc * 10 + d;
  }
  Ok(acc)
}

fn c_add(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a > HI - b { return Err("overflow"); }
  if b < 0 && a < lo() - b { return Err("overflow"); }
  Ok(a + b)
}

fn c_sub(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 && a < lo() + b { return Err("overflow"); }
  if b < 0 && a > HI + b { return Err("overflow"); }
  Ok(a - b)
}

fn c_mul(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a > 0 && b > 0 && a > HI / b { return Err("overflow"); }
  if a > 0 && b < 0 && b < lo() / a { return Err("overflow"); }
  if a < 0 && b > 0 && a < lo() / b { return Err("overflow"); }
  if a < 0 && b < 0 && a < HI / b { return Err("overflow"); }
  Ok(a * b)
}

fn c_div(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 && a == lo() { return Err("overflow"); }
  Ok(a / b)
}

fn c_rem(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn c_pow(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  if a == 0 {
    if b == 0 { return Ok(1); }
    return Ok(0);
  }
  if a == 1 { return Ok(1); }
  if a == -1 {
    if b % 2 == 0 { return Ok(1); }
    return Ok(-1);
  }
  if b > 64 { return Err("overflow"); }
  let mut r = 1;
  let mut i = 0;
  while i < b {
    r = c_mul(r, a)?;
    i += 1;
  }
  Ok(r)
}

fn eval(n: Node, vars: Map<Str, Int>) -> Result<Int, Str> {
  let op = n.op;
  if op == "num" { return parse_lit(n.name); }
  if op == "var" {
    return match vars.get(n.name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n.name),
    };
  }
  if op == "neg" {
    let v = eval(n.kids[0], vars)?;
    return c_sub(0, v);
  }
  if op == "call" {
    let f = n.name;
    let k = n.kids.len();
    if f == "abs" {
      if k != 1 { return Err("wrong number of arguments to abs"); }
      let a = eval(n.kids[0], vars)?;
      if a < 0 { return c_sub(0, a); }
      return Ok(a);
    }
    if f == "min" || f == "max" {
      if k != 2 { return Err("wrong number of arguments to " + f); }
      let a = eval(n.kids[0], vars)?;
      let b = eval(n.kids[1], vars)?;
      if f == "min" {
        if a < b { return Ok(a); }
        return Ok(b);
      }
      if a > b { return Ok(a); }
      return Ok(b);
    }
    return Err("unknown function " + f);
  }
  let a = eval(n.kids[0], vars)?;
  let b = eval(n.kids[1], vars)?;
  if op == "+" { return c_add(a, b); }
  if op == "-" { return c_sub(a, b); }
  if op == "*" { return c_mul(a, b); }
  if op == "/" { return c_div(a, b); }
  if op == "%" { return c_rem(a, b); }
  c_pow(a, b)
}

fn eval_line(line: Str, vars: Map<Str, Int>) -> Result<Bound, Str> {
  let toks = match tokenize(line.to_bytes()) {
    Some(t) => t,
    None => { return Err("syntax error"); }
  };
  if toks.len() == 0 { return Err("syntax error"); }
  if name_at(toks, 0) == "let" {
    let nm = name_at(toks, 1);
    if nm == "" || sym_at(toks, 2) != "=" { return Err("syntax error"); }
    let node = match parse_full(toks, 3) {
      Some(x) => x,
      None => { return Err("syntax error"); }
    };
    let v = eval(node, vars)?;
    return Ok(Bound { is_let: true, name: nm, value: v });
  }
  let node = match parse_full(toks, 0) {
    Some(x) => x,
    None => { return Err("syntax error"); }
  };
  let v = eval(node, vars)?;
  Ok(Bound { is_let: false, name: "", value: v })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut out = "";
  let mut vars: Map<Str, Int> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    if line.trim() == "" { continue; }
    n += 1;
    let prefix = n.to_str() + ": ";
    match eval_line(line, vars) {
      Ok(b) => {
        if b.is_let {
          vars.insert(b.name, b.value);
          out = out + prefix + b.name + " = " + b.value.to_str() + "\n";
        } else {
          out = out + prefix + b.value.to_str() + "\n";
        }
      }
      Err(m) => {
        out = out + prefix + "error: " + m + "\n";
      }
    }
  }
  Ok(out)
}

