  Ok(r)
}

fn eval(n: Node, vars: Map<Str, Int>) -> Result<Int, Str> {
  let op = n.op;
  if op == "num" { return parse_lit(n.name); }
  if op == "var" {
    return match vars.get(n.name) {
      Some(v) => Ok(v),
      None => Err("unknown variable " + n.name),
    };
  }
  if op == "neg" {
    let v = eval(n.kids[0], vars)?;
    return c_sub(0, v);
  }
  if op == "call" {
    let f = n.name;
    let k = n.kids.len();
    if f == "abs" {
      if k != 1 { return Err("wrong number of arguments to abs"); }
      let a = eval(n.kids[0], vars)?;
      if a < 0 { return c_sub(0, a); }
      return Ok(a);
    }
    if f == "min" || f == "max" {
      if k != 2 { return Err("wrong number of arguments to " + f); }
      let a = eval(n.kids[0], vars)?;
      let b = eval(n.kids[1], vars)?;
      if f == "min" {
        if a < b { return Ok(a); }
        return Ok(b);
      }
      if a > b { return Ok(a); }
      return Ok(b);
    }
    return Err("unknown function " + f);
  }
  let a = eval(n.kids[0], vars)?;
  let b = eval(n.kids[1], vars)?;
  if op == "+" { return c_add(a, b); }
  if op == "-" { return c_sub(a, b); }
  if op == "*" { return c_mul(a, b); }
  if op == "/" { return c_div(a, b); }
  if op == "%" { return c_rem(a, b); }
  c_pow(a, b)
}

fn eval_line(line: Str, vars: Map<Str, Int>) -> Result<Bound, Str> {
  let toks = match tokenize(line.to_bytes()) {
    Some(t) => t,
    None => { return Err("syntax error"); }
  };
  if toks.len() == 0 { return Err("syntax error"); }
  if name_at(toks, 0) == "let" {
    let nm = name_at(toks, 1);
    if nm == "" || sym_at(toks, 2) != "=" { return Err("syntax error"); }
    let node = match parse_full(toks, 3) {
      Some(x) => x,
      None => { return Err("syntax error"); }
    };
    let v = eval(node, vars)?;
    return Ok(Bound { is_let: true, name: nm, value: v });
  }
  let node = match parse_full(toks, 0) {
    Some(x) => x,
    None => { return Err("syntax error"); }
  };
  let v = eval(node, vars)?;
  Ok(Bound { is_let: false, name: "", value: v })
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let lines = text.lines();
  let mut out = "";
  let mut vars: Map<Str, Int> = Map::new();
  let mut i = 0;
  while i < lines.len() {
    let line = lines[i];
    i += 1;
    if line.trim() == "" { continue; }
    let prefix = i.to_str() + ": ";
    match eval_line(line, vars) {
      Ok(b) => {
        if b.is_let {
          vars.insert(b.name, b.value);
          out = out + prefix + b.name + " = " + b.value.to_str() + "\n";
        } else {
          out = out + prefix + b.value.to_str() + "\n";
        }
      }
      Err(m) => {
        out = out + prefix + "error: " + m + "\n";
      }
    }
  }
  Ok(out)
}

enum Tok { Num(Str), Name(Str), Sym(Str) }

enum Expr {
  Lit(Str),
  Var(Str),
  Neg(List<Expr>),
  Bin(Str, List<Expr>),
  Call(Str, List<Expr>),
}

enum Stmt { Let(Str, Expr), Show(Expr) }

struct PE { e: Expr, p: Int }

struct Step { text: Str, env: Map<Str, Int> }

// LO is the smallest Int plus one, so LO - 1 is the smallest Int.
const HI: Int = 9223372036854775807;
const LO: Int = -9223372036854775807;

fn is_digit(c: Str) -> Bool { c >= "0" && c <= "9" }

fn is_alpha(c: Str) -> Bool { (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") }

fn is_sym_char(c: Str) -> Bool {
  c == "+" || c == "-" || c == "*" || c == "/" || c == "%" || c == "^"
    || c == "(" || c == ")" || c == "," || c == "="
}

fn tokenize(line: Str) -> Result<List<Tok>, Str> {
  let cs = line.chars();
  let n = cs.len();
  let mut out: List<Tok> = [];
  let mut i = 0;
  while i < n {
    let c = cs[i];
    if c == " " {
      i += 1;
    } else if is_digit(c) {
      let mut s = "";
      while i < n {
        if !is_digit(cs[i]) { break; }
        s = s + cs[i];
        i += 1;
      }
      out.push(Tok::Num(s));
    } else if is_alpha(c) || c == "_" {
      let mut s = "";
      while i < n {
        let d = cs[i];
        if !(is_alpha(d) || is_digit(d) || d == "_") { break; }
        s = s + d;
        i += 1;
      }
      out.push(Tok::Name(s));
    } else if is_sym_char(c) {
      out.push(Tok::Sym(c));
      i += 1;
    } else {
      return Err("syntax error");
    }
  }
  Ok(out)
}

fn sym_at(ts: List<Tok>, p: Int) -> Str {
  if p >= ts.len() { return ""; }
  match ts[p] {
    Tok::Sym(s) => s,
    _ => "",
  }
}

fn name_at(ts: List<Tok>, p: Int) -> Str {
  if p >= ts.len() { return ""; }
  match ts[p] {
    Tok::Name(s) => s,
    _ => "",
  }
}

fn parse_expr(ts: List<Tok>, p: Int) -> Result<PE, Str> {
  let first = parse_term(ts, p)?;
  let mut e = first.e;
  let mut q = first.p;
  loop {
    let op = sym_at(ts, q);
    if op != "+" && op != "-" { break; }
    let r = parse_term(ts, q + 1)?;
    e = Expr::Bin(op, [e, r.e]);
    q = r.p;
  }
  Ok(PE { e: e, p: q })
}

fn parse_term(ts: List<Tok>, p: Int) -> Result<PE, Str> {
  let first = parse_factor(ts, p)?;
  let mut e = first.e;
  let mut q = first.p;
  loop {
    let op = sym_at(ts, q);
    if op != "*" && op != "/" && op != "%" { break; }
    let r = parse_factor(ts, q + 1)?;
    e = Expr::Bin(op, [e, r.e]);
    q = r.p;
  }
  Ok(PE { e: e, p: q })
}

fn parse_factor(ts: List<Tok>, p: Int) -> Result<PE, Str> {
  if sym_at(ts, p) == "-" {
    let r = parse_factor(ts, p + 1)?;
    return Ok(PE { e: Expr::Neg([r.e]), p: r.p });
  }
  parse_power(ts, p)
}

fn parse_power(ts: List<Tok>, p: Int) -> Result<PE, Str> {
  let a = parse_atom(ts, p)?;
  if sym_at(ts, a.p) == "^" {
    let b = parse_factor(ts, a.p + 1)?;
    return Ok(PE { e: Expr::Bin("^", [a.e, b.e]), p: b.p });
  }
  Ok(PE { e: a.e, p: a.p })
}

fn parse_atom(ts: List<Tok>, p: Int) -> Result<PE, Str> {
  if p >= ts.len() { return Err("syntax error"); }
  match ts[p] {
    Tok::Num(s) => Ok(PE { e: Expr::Lit(s), p: p + 1 }),
    Tok::Name(s) => {
      if sym_at(ts, p + 1) != "(" {
        return Ok(PE { e: Expr::Var(s), p: p + 1 });
      }
      let first = parse_expr(ts, p + 2)?;
      let mut args: List<Expr> = [first.e];
      let mut q = first.p;
      loop {
        if sym_at(ts, q) != "," { break; }
        let a = parse_expr(ts, q + 1)?;
        args.push(a.e);
        q = a.p;
      }
      if sym_at(ts, q) != ")" { return Err("syntax error"); }
      Ok(PE { e: Expr::Call(s, args), p: q + 1 })
    }
    Tok::Sym(s) => {
      if s != "(" { return Err("syntax error"); }
      let a = parse_expr(ts, p + 1)?;
      if sym_at(ts, a.p) != ")" { return Err("syntax error"); }
      Ok(PE { e: a.e, p: a.p + 1 })
    }
  }
}

fn parse_stmt(ts: List<Tok>) -> Result<Stmt, Str> {
  if name_at(ts, 0) == "let" {
    let nm = name_at(ts, 1);
    if nm == "" || sym_at(ts, 2) != "=" { return Err("syntax error"); }
    let r = parse_expr(ts, 3)?;
    if r.p != ts.len() { return Err("syntax error"); }
    return Ok(Stmt::Let(nm, r.e));
  }
  let r = parse_expr(ts, 0)?;
  if r.p != ts.len() { return Err("syntax error"); }
  Ok(Stmt::Show(r.e))
}

fn add_ck(a: Int, b: Int) -> Result<Int, Str> {
  if b > 0 { if a > HI - b { return Err("overflow"); } }
  if b < 0 { if a < LO - 1 - b { return Err("overflow"); } }
  Ok(a + b)
}

fn sub_ck(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { if a > HI + b { return Err("overflow"); } }
  if b > 0 { if a < LO - 1 + b { return Err("overflow"); } }
  Ok(a - b)
}

fn mul_ck(a: Int, b: Int) -> Result<Int, Str> {
  if a == 0 || b == 0 { return Ok(0); }
  if a > 0 {
    if b > 0 {
      if a > HI / b { return Err("overflow"); }
    } else {
      if b < (LO - 1) / a { return Err("overflow"); }
    }
  } else {
    if b > 0 {
      if a < (LO - 1) / b { return Err("overflow"); }
    } else {
      if b < HI / a { return Err("overflow"); }
    }
  }
  Ok(a * b)
}

fn div_ck(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 {
    if a == LO - 1 { return Err("overflow"); }
  }
  Ok(a / b)
}

fn rem_ck(a: Int, b: Int) -> Result<Int, Str> {
  if b == 0 { return Err("division by zero"); }
  if b == -1 { return Ok(0); }
  Ok(a % b)
}

fn pow_ck(a: Int, b: Int) -> Result<Int, Str> {
  if b < 0 { return Err("negative exponent"); }
  let mut result = 1;
  let mut base = a;
  let mut e = b;
  loop {
    if e == 0 { break; }
    if e % 2 == 1 { result = mul_ck(result, base)?; }
    e = e / 2;
    if e > 0 { base = mul_ck(base, base)?; }
  }
  Ok(result)
}

fn neg_ck(a: Int) -> Result<Int, Str> {
  if a == LO - 1 { return Err("overflow"); }
  Ok(-a)
}

fn abs_ck(a: Int) -> Result<Int, Str> {
  if a == LO - 1 { return Err("overflow"); }
  if a < 0 { return Ok(-a); }
  Ok(a)
}

fn binop(op: Str, a: Int, b: Int) -> Result<Int, Str> {
  if op == "+" { return add_ck(a, b); }
  if op == "-" { return sub_ck(a, b); }
  if op == "*" { return mul_ck(a, b); }
  if op == "/" { return div_ck(a, b); }
  if op == "%" { return rem_ck(a, b); }
  pow_ck(a, b)
}

fn eval(env: Map<Str, Int>, e: Expr) -> Result<Int, Str> {
  match e {
    Expr::Lit(s) => {
      match s.parse_int() {
        Some(v) => Ok(v),
        None => Err("overflow"),
      }
    }
    Expr::Var(name) => {
      match env.get(name) {
        Some(v) => Ok(v),
        None => Err("unknown variable " + name),
      }
    }
    Expr::Neg(xs) => {
      let a = eval(env, xs[0])?;
      neg_ck(a)
    }
    Expr::Bin(op, xs) => {
      let a = eval(env, xs[0])?;
      let b = eval(env, xs[1])?;
      binop(op, a, b)
    }
    Expr::Call(name, xs) => call(env, name, xs),
  }
}

fn call(env: Map<Str, Int>, name: Str, xs: List<Expr>) -> Result<Int, Str> {
  if name == "min" || name == "max" {
    if xs.len() != 2 { return Err("wrong number of arguments to " + name); }
    let a = eval(env, xs[0])?;
    let b = eval(env, xs[1])?;
    if name == "min" { return Ok(a.min(b)); }
    return Ok(a.max(b));
  }
  if name == "abs" {
    if xs.len() != 1 { return Err("wrong number of arguments to abs"); }
    let a = eval(env, xs[0])?;
    return abs_ck(a);
  }
  Err("unknown function " + name)
}

fn err_line(n: Int, m: Str) -> Str {
  n.to_str() + ": error: " + m
}

fn run_line(line: Str, n: Int, env: Map<Str, Int>) -> Step {
  let toks = match tokenize(line) {
    Ok(t) => t,
    Err(m) => return Step { text: err_line(n, m), env: env },
  };
  if toks.len() == 0 { return Step { text: "", env: env }; }
  let stmt = match parse_stmt(toks) {
    Ok(s) => s,
    Err(m) => return Step { text: err_line(n, m), env: env },
  };
  match stmt {
    Stmt::Let(name, e) => match eval(env, e) {
      Ok(v) => {
        let mut env2 = env;
        env2.insert(name, v);
        Step { text: n.to_str() + ": " + name + " = " + v.to_str(), env: env2 }
      }
      Err(m) => Step { text: err_line(n, m), env: env },
    },
    Stmt::Show(e) => match eval(env, e) {
      Ok(v) => Step { text: n.to_str() + ": " + v.to_str(), env: env },
      Err(m) => Step { text: err_line(n, m), env: env },
    },
  }
}

fn main(input: Dir) -> Result<Str, IoErr> {
  let text = input.read("program.txt")?.to_str();
  let mut out: List<Str> = [];
  let mut env: Map<Str, Int> = Map::new();
  let mut n = 0;
  for line in text.lines() {
    n += 1;
    let st = run_line(line, n, env);
    env = st.env;
    if st.text != "" { out.push(st.text); }
  }
  Ok(out.join("\n"))
}

