import os
import sys

OPEN_FOR = {'(': ')', '[': ']', '{': '}'}
PAIR = {')': '(', ']': '[', '}': '{'}


def check(line):
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in OPEN_FOR:
            stack.append(ch)
        elif ch in PAIR:
            if not stack:
                return f"col {i}: unexpected {ch}"
            top = stack.pop()
            if top != PAIR[ch]:
                return f"col {i}: expected {OPEN_FOR[top]}, found {ch}"
    if stack:
        return f"unclosed {OPEN_FOR[stack[-1]]}"
    return "ok"


def main():
