import os
import sys

PAIR = {'(': ')', '[': ']', '{': '}'}
CLOSE = set(PAIR.values())


def fast(line):
    """Single stack pass. Returns the verdict for the line."""
    stack = []
    for idx, ch in enumerate(line, 1):
        if ch in PAIR:
            stack.append((ch, idx))
        elif ch in CLOSE:
            if not stack:
                return ('unexpected', idx, ch)
            top, _ = stack[-1]
            if PAIR[top] != ch:
                return ('mismatch', idx, PAIR[top], ch)
            stack.pop()
    if stack:
        return ('unclosed', PAIR[stack[-1][0]])
    return ('ok',)


def run(s):
    """
    Independent confirmation pass. Explores every assignment that pairs each
    closer with some earlier unmatched opener of the same kind, keeping only
    assignments whose pairs do not cross. Each state is the tuple of positions
    of still-unmatched openers. Returns the set of reachable end states; an
    empty set means some closer cannot be paired in any valid assignment.
    """
    states = {()}
    for i, ch in enumerate(s):
        if ch in PAIR:
            states = {st + (i,) for st in states}
        elif ch in CLOSE:
            nxt = set()
            for st in states:
                for j, o in enumerate(st):
                    if PAIR[s[o]] != ch:
                        continue
                    # A later unmatched opener would be paired after this
                    # closer, producing crossing pairs; reject that choice.
                    if j != len(st) - 1:
                        continue
                    nxt.add(st[:j] + st[j + 1:])
            states = nxt
            if not states:
                return states
    return states


def confirm(line, verdict):
    if verdict[0] == 'ok':
        return () in run(line)
    if verdict[0] == 'unclosed':
        states = run(line)
        return bool(states) and () not in states
    # unexpected / mismatch: the first unmatchable closer is at column N.
    n = verdict[1]
    return bool(run(line[:n - 1])) and not run(line[:n])


def main():
    path = os.path.join(os.environ["INPUT"], "snippets.txt")
    with open(path, encoding="latin-1", newline="") as f:
        data = f.read()

    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    out = []
    all_confirmed = True
    for lineno, raw in enumerate(lines, 1):
        line = raw.rstrip("\r")
        v = fast(line)
        if not confirm(line, v):
            all_confirmed = False
            print(f"line {lineno}: verdict not confirmed", file=sys.stderr)

        if v[0] == 'ok':
            out.append("ok")
        elif v[0] == 'unclosed':
            out.append(f"unclosed {v[1]}")
        elif v[0] == 'unexpected':
            out.append(f"col {v[1]}: unexpected {v[2]}")
        else:
            out.append(f"col {v[1]}: expected {v[2]}, found {v[3]}")

    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
    if not all_confirmed:
        sys.exit(1)


if __name__ == "__main__":
    main()

