import re
import time

# Window-end detection: the README says the collector ends the window with a
# sentinel line, but the excerpt I could see cuts off before naming it. So this
# program does not depend on the sentinel's text. It keeps polling the growing
# file and stops only after it has not grown for QUIET seconds. If the sentinel
# string is known, replace the quiet-period test with a check for that line.
QUIET = 30.0   # seconds without growth before the window is treated as complete
POLL = 0.5     # seconds between polls

RECORD_MS = re.compile(r'-?[0-9]+')
groups = {}    # (method, path) -> list of millis


def add_line(raw):
    parts = raw.decode("utf-8", errors="replace").split()
    if len(parts) != 3:
        return
    method, path, ms = parts
    if not RECORD_MS.fullmatch(ms):
        return
    groups.setdefault((method, path), []).append(int(ms))


def read_from(fpath, offset):
    try:
        with open(fpath, "rb") as f:
            f.seek(offset)
            return f.read()
    except FileNotFoundError:
        return b""


def main():
    fpath = os.path.join(os.environ["INPUT"], "timings.log")
    offset = 0
    buf = b""
    last_growth = time.monotonic()

    while True:
        data = read_from(fpath, offset)
        if data:
            offset += len(data)
            buf += data
            last_growth = time.monotonic()
            # Only complete lines are processed; the trailing fragment waits.
            *lines, buf = buf.split(b"\n")
            for ln in lines:
                add_line(ln)
        elif time.monotonic() - last_growth >= QUIET:
            break
        else:
            time.sleep(POLL)

    if buf:
        add_line(buf)

    def key(k):
        return (k[0].encode("utf-8"), k[1].encode("utf-8"))

    for method, path in sorted(groups, key=key):
        ts = sorted(groups[(method, path)])
        n = len(ts)

        def rank(p):
            # nearest-rank: t[ceil(p*n/100)] with 1-based indexing
            return ts[(p * n + 99) // 100 - 1]

        print(f"{method} {path} count={n} p50={rank(50)} p95={rank(95)} max={ts[-1]}")


