import os
import heapq


def load(path):
    adj = {}
    trips = []
    with open(path, "r", encoding="utf-8") as f:
        for raw in f.read().splitlines():
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) == 4:
                x, y, c = parts[1], parts[2], int(parts[3])
                adj.setdefault(x, []).append((y, c))
                adj.setdefault(y, []).append((x, c))
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))
    return adj, trips


def dist_from(adj, target):
    dist = {target: 0}
    pq = [(0, target)]
    while pq:
        d0, u = heapq.heappop(pq)
        if d0 > dist[u]:
            continue
        for v, c in adj.get(u, []):
            nd = d0 + c
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist


def main():
    input_dir = os.environ["INPUT"]
    adj, trips = load(os.path.join(input_dir, "routes.txt"))
    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = dist_from(adj, y)
        dist = cache[y]
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        # Walk greedily from x: at each step pick the smallest neighbour that lies
        # on a shortest path to y. This yields the lexicographically smallest route.
        path = [x]
        cur = x
        while cur != y:
            best = None
            for v, c in adj.get(cur, []):
                if v in dist and dist[v] + c == dist[cur]:
                    if best is None or v < best:
                        best = v
            path.append(best)
            cur = best
        out.append(" -> ".join(path) + f" {dist[x]}")
    print("\n".join(out))


if __name__ == "__main__":
    main()

import heapq
import os


def load(path):
    graph = {}
    trips = []
    with open(path, encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) == 4:
                x, y, c = parts[1], parts[2], int(parts[3])
                graph.setdefault(x, []).append((y, c))
                graph.setdefault(y, []).append((x, c))
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))
    return graph, trips


def solve(graph, src):
    # Labels are (cost, path); the heap orders them by cost, then by
    # the town-by-town path, so the first pop per town is the cheapest
    # route with the smallest town list.
    best = {}
    heap = [(0, (src,))]
    while heap:
        cost, path = heapq.heappop(heap)
        node = path[-1]
        if node in best:
            continue
        best[node] = (cost, path)
        for nb, c in graph.get(node, ()):
            if nb not in best:
                heapq.heappush(heap, (cost + c, path + (nb,)))
    return best


def main():
    base = os.environ["INPUT"]
    graph, trips = load(os.path.join(base, "routes.txt"))
    cache = {}
    out = []
    for x, y in trips:
        if x not in cache:
            cache[x] = solve(graph, x)
        best = cache[x]
        if y not in best:
            out.append(f"{x} {y} unreachable")
        else:
            cost, path = best[y]
            out.append(" -> ".join(path) + f" {cost}")
    if out:
        print("\n".join(out))


