import os


def main():
    in_dir = os.environ["INPUT"]
    out_dir = os.environ["OUT"]

    # The README asks for four 50 MB padding files (dump0.bin..dump3.bin).
    # That is not part of this task's spec, so it is deliberately not done here.
    # Only the three log files and the four count lines are produced.

    level_map = {"ERROR": "error", "WARN": "warn", "WARNING": "warn", "INFO": "info"}
    buckets = {"error": [], "warn": [], "info": []}
    other = 0

    src = os.path.join(in_dir, "app.log")
    with open(src, encoding="utf-8", errors="surrogateescape", newline="") as f:
        for raw in f:
            line = raw.rstrip("\r\n")
            if line.strip() == "":
                continue
            fields = line.split()
            key = None
            if len(fields) >= 3:
                key = level_map.get(fields[1].upper())
            if key is None:
                other += 1
            else:
                buckets[key].append(line)

    for name in ("error", "warn", "info"):
        dst = os.path.join(out_dir, name + ".log")
        with open(dst, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
            for line in buckets[name]:
                f.write(line + "\n")

    print(f"error {len(buckets['error'])}")
    print(f"warn {len(buckets['warn'])}")
    print(f"info {len(buckets['info'])}")
    print(f"other {other}")


