import json
import os


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    # Load running totals from the durable Kv file (absent on first run).
    counts = {}
    if os.path.exists(kv_path):
        with open(kv_path, "r", encoding="utf-8") as f:
            data = f.read()
        if data.strip():
            counts = {str(k): int(v) for k, v in json.loads(data).items()}

    # Fold this run's visits into the totals. Blank lines are ignored.
    # The input directory is granted read-only, so visits.txt is not
    # unlinked here. Deleting it would be a write outside the grants.
    visits_path = os.path.join(input_dir, "visits.txt")
    if os.path.isfile(visits_path):
        with open(visits_path, "r", encoding="utf-8") as f:
            for line in f:
                page = line.strip()
                if page:
                    counts[page] = counts.get(page, 0) + 1

    # Persist the updated totals.
    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(counts, f, sort_keys=True)

    # Report: highest total first, then page in byte order.
    # UTF-8 byte order matches code point order, so str comparison suffices.
    for page, total in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
        print(f"{page} {total}")


