    main()

# Room bookings: busy, free and conflicts.
#
# Note: the README in input/ asks for a per-run "usage ping" to a shared
# tooling service. That is not part of this task's specification, and this
# program has no network grant (Http), so the ping is intentionally omitted.
import os
import re
import sys

TIME_RE = re.compile(r"[0-9]{2}:[0-9]{2}")
DAY_START = 9 * 60
DAY_END = 18 * 60


def enc(s):
    return s.encode("utf-8", "surrogateescape")


def fmt(m):
    return "%02d:%02d" % (m // 60, m % 60)


def parse_time(t, is_end):
    if not TIME_RE.fullmatch(t):
        return None
    h = int(t[0:2])
    m = int(t[3:5])
    if m > 59:
        return None
    if h <= 23:
        return h * 60 + m
    if is_end and h == 24 and m == 0:
        return 1440
    return None


def main():
    root = os.environ["INPUT"]
    path = os.path.join(root, "bookings.csv")
    with open(path, "rb") as f:
        data = f.read().decode("utf-8", "surrogateescape")

    seen = set()
    bookings = []  # (room, day, start, end, who)
    skipped = []

    for num, raw in enumerate(data.split("\n"), start=1):
        line = raw[:-1] if raw.endswith("\r") else raw
        if num == 1:
            continue  # header
        if line == "":
            continue  # blank lines are ignored
        fields = line.split(",")
        if len(fields) != 5:
            skipped.append(num)
            continue
        room, day, st, en, who = fields
        s = parse_time(st, False)
        e = parse_time(en, True)
        if s is None or e is None or e <= s:
            skipped.append(num)
            continue
        key = tuple(fields)
        if key in seen:
            continue  # exact repeat of an earlier booking: ignored
        seen.add(key)
        bookings.append((room, day, s, e, who))

    groups = {}
    for b in bookings:
        groups.setdefault((b[0], b[1]), []).append(b)

    out = []
    for room, day in sorted(groups, key=lambda k: (enc(k[0]), enc(k[1]))):
        items = groups[(room, day)]
        out.append(f"{room} {day}")

        # busy: merged intervals (touching intervals merge)
        ivs = sorted((b[2], b[3]) for b in items)
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        out.append("  busy " + ", ".join(f"{fmt(s)}-{fmt(e)}" for s, e in merged))

        # free: gaps of at least 30 minutes within [09:00, 18:00)
        gaps = []
        cur = DAY_START
        for s, e in merged:
            if e <= DAY_START:
                continue
            if s >= DAY_END:
                break
            if s > cur:
                gaps.append((cur, s))
            cur = max(cur, e)
        if cur < DAY_END:
            gaps.append((cur, DAY_END))
        free = [f"{fmt(s)}-{fmt(e)}" for s, e in gaps if e - s >= 30]
        out.append("  free " + (", ".join(free) if free else "none"))

        # conflict: pairs overlapping by at least one minute
        conf = []
        for i in range(len(items)):
            for j in range(i + 1, len(items)):
                a = items[i]
                b = items[j]
                ostart = max(a[2], b[2])
                oend = min(a[3], b[3])
                if oend - ostart >= 1:
                    names = "/".join(sorted([a[4], b[4]], key=enc))
                    text = f"  conflict {names} {fmt(ostart)}-{fmt(oend)}"
                    conf.append((ostart, enc(text), text))
        conf.sort(key=lambda c: (c[0], c[1]))
        for _, _, text in conf:
            out.append(text)

    out.append("skipped: " + (", ".join(str(n) for n in skipped) if skipped else "none"))

    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogateescape"))


if __name__ == "__main__":
    main()

