def bad_const(name):
    raise ValueError("invalid JSON constant: " + name)


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def check(schema, v, path, errs):
    t = schema.get("type")

    if t == "object":
        if not isinstance(v, dict):
            errs.append((path, "expected object"))
            return
        props = schema.get("properties", {})
        for name in schema.get("required", []):
            if name not in v:
                errs.append((path + "." + name, "missing required field"))
        if not schema.get("additional", True):
            for k in v:
                if k not in props:
                    errs.append((path + "." + k, "unexpected field"))
        for k, sub in props.items():
            if k in v:
                check(sub, v[k], path + "." + k, errs)

    elif t == "array":
        if not isinstance(v, list):
            errs.append((path, "expected array"))
            return
        if "min_items" in schema and len(v) < schema["min_items"]:
            errs.append((path, "fewer than %s items" % schema["min_items"]))
        if "items" in schema:
            for i, el in enumerate(v):
                check(schema["items"], el, "%s[%d]" % (path, i), errs)

    elif t == "string":
        if not isinstance(v, str):
            errs.append((path, "expected string"))
            return
        n = len(v)  # code points
        if "min_length" in schema and n < schema["min_length"]:
            errs.append((path, "shorter than %s" % schema["min_length"]))
        elif "max_length" in schema and n > schema["max_length"]:
            errs.append((path, "longer than %s" % schema["max_length"]))
        elif "enum" in schema and v not in schema["enum"]:
            errs.append((path, "not in enum"))

    elif t == "integer":
        if not is_int(v):
            errs.append((path, "expected integer"))
            return
        if "minimum" in schema and v < schema["minimum"]:
            errs.append((path, "less than %s" % schema["minimum"]))
        elif "maximum" in schema and v > schema["maximum"]:
            errs.append((path, "greater than %s" % schema["maximum"]))

    elif t == "number":
        if not is_num(v):
            errs.append((path, "expected number"))
            return
        if "minimum" in schema and v < schema["minimum"]:
            errs.append((path, "less than %s" % schema["minimum"]))
        elif "maximum" in schema and v > schema["maximum"]:
            errs.append((path, "greater than %s" % schema["maximum"]))

    elif t == "boolean":
        if not isinstance(v, bool):
            errs.append((path, "expected boolean"))

    elif t == "null":
        if v is not None:
            errs.append((path, "expected null"))


def sort_key(err):
    p, m = err
    return (p.encode("utf-8", "surrogatepass"), m.encode("utf-8", "surrogatepass"))


def main():
    with open(os.path.join(INPUT, "schema.json"), "r", encoding="utf-8") as f:
        schema = json.load(f)

    with open(os.path.join(INPUT, "records.jsonl"), "rb") as f:
        raw = f.read()

    out = []
    total = 0
    valid = 0
    for n, line in enumerate(raw.split(b"\n"), 1):
        if line.strip() == b"":
            continue
        total += 1
        try:
            rec = json.loads(line.decode("utf-8"), parse_constant=bad_const)
        except Exception:
            out.append("line %d: invalid JSON" % n)
            continue

        errs = []
        check(schema, rec, "$", errs)
        if not errs:
            valid += 1
            out.append("line %d: ok" % n)
        else:
            errs.sort(key=sort_key)
            for p, m in errs:
                out.append("line %d: %s: %s" % (n, p, m))

    out.append("valid %d of %d" % (valid, total))
    sys.stdout.write("\n".join(out) + "\n")


