def reject_constant(name):
    # NaN and Infinity are not valid JSON, so treat them as unparseable.
    raise ValueError("invalid constant " + name)


def is_integer(v):
    return isinstance(v, int) and not isinstance(v, bool)


def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


TYPE_CHECKS = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "integer": is_integer,
    "number": is_number,
    "boolean": lambda v: isinstance(v, bool),
    "null": lambda v: v is None,
}


def validate(value, schema, path, errs):
    t = schema["type"]
    if not TYPE_CHECKS[t](value):
        errs.append((path, "expected " + t))
        return

    if t == "object":
        properties = schema.get("properties", {})
        for name in schema.get("required", []):
            if name not in value:
                errs.append((path + "." + name, "missing required field"))
        for key, sub in value.items():
            child = path + "." + key
            if key in properties:
                validate(sub, properties[key], child, errs)
            elif schema.get("additional", True) is False:
                errs.append((child, "unexpected field"))

    elif t == "array":
        min_items = schema.get("min_items")
        if min_items is not None and len(value) < min_items:
            errs.append((path, "fewer than %d items" % min_items))
        items = schema.get("items")
        if items is not None:
            for i, el in enumerate(value):
                validate(el, items, "%s[%d]" % (path, i), errs)

    elif t == "string":
        # len() on str counts Unicode code points.
        min_len = schema.get("min_length")
        max_len = schema.get("max_length")
        enum = schema.get("enum")
        if min_len is not None and len(value) < min_len:
            errs.append((path, "shorter than %d" % min_len))
        elif max_len is not None and len(value) > max_len:
            errs.append((path, "longer than %d" % max_len))
        elif enum is not None and value not in enum:
            errs.append((path, "not in enum"))

    elif t in ("integer", "number"):
        minimum = schema.get("minimum")
        maximum = schema.get("maximum")
        if minimum is not None and value < minimum:
            errs.append((path, "less than %d" % minimum))
        elif maximum is not None and value > maximum:
            errs.append((path, "greater than %d" % maximum))


