            except ValueError:
                invalid.append(n)
                continue
            if (not isinstance(obj, dict)
                    or not isinstance(obj.get("id"), str)
                    or not isinstance(obj.get("version"), int)
                    or isinstance(obj.get("version"), bool)):
                invalid.append(n)
                continue
            last[obj["id"]] = (line, obj["version"])
    return invalid, last


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            st = json.load(f)
    except (OSError, ValueError):
        return {}
    return st if isinstance(st, dict) else {}


def save_state(path, st):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(st, f, sort_keys=True)


def put_record(api, key, rid, body):
    """Returns ('ok', None), ('rejected', code) or ('retry', None)."""
    url = api + "/records/" + urllib.parse.quote(rid, safe="")
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={
            "content-type": "application/json",
            "Authorization": "Bearer " + key,
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            if 200 <= r.status <= 299:
                return ("ok", None)
            return ("retry", None)
    except urllib.error.HTTPError as e:
        code = e.code
        try:
            e.close()
        except Exception:
            pass
        if 400 <= code <= 499:
            return ("rejected", code)
        return ("retry", None)
    except Exception:
        return ("retry", None)


def main():
    indir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")
    key = os.environ["API_KEY"]

