        for rid in pending:
            line, version = last[rid]
            attempts[rid] += 1
            status, code = put_record(api, key, rid, line.encode("utf-8"))
            if status == "ok":
                st[rid] = version
                results[rid] = "synced"
            elif status == "rejected":
                results[rid] = "rejected %d" % code
            elif attempts[rid] >= 3:
                results[rid] = "failed"
            else:
                next_pending.append(rid)
        pending = next_pending
        save_state(state_path, st)

    for n in invalid:
        print("line %d invalid" % n)

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        res = results[rid]
        print("%s %s" % (rid, res))
        if res == "synced":
            counts["synced"] += 1
        elif res == "unchanged":
            counts["unchanged"] += 1
        elif res.startswith("rejected"):
            counts["rejected"] += 1
        else:
            counts["failed"] += 1

    print("synced %d unchanged %d rejected %d failed %d" % (
