    rid = obj.get("id")
    ver = obj.get("version")
    if not isinstance(rid, str):
        return None
    if not isinstance(ver, int) or isinstance(ver, bool):
        return None
    return rid, ver, text


def push(api, key, rid, text):
    """Return ('synced',), ('rejected', code) or ('failed',)."""
    url = api + "/records/" + urllib.parse.quote(rid, safe="")
    body = text.encode("utf-8")
    for _attempt in range(3):
        req = urllib.request.Request(
            url,
            data=body,
            method="PUT",
            headers={
                "content-type": "application/json",
                "Authorization": "Bearer " + key,
            },
        )
        code = None
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                code = resp.status
        except urllib.error.HTTPError as e:
            code = e.code
        except Exception:
            code = None  # no response at all
        if code is not None and 200 <= code < 300:
            return ("synced",)
        if code is not None and 400 <= code < 500:
            return ("rejected", code)
        # 5xx, other statuses, or no response: retry within the budget
    return ("failed",)


def main():
