    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")
    key = os.environ["API_KEY"]

    # Load state: id -> last version pushed successfully.
    state = {}
    if os.path.exists(state_path):
        with open(state_path, "rb") as f:
            state = json.loads(f.read().decode("utf-8") or "{}")

    # Parse input.
    with open(os.path.join(input_dir, "records.jsonl"), "rb") as f:
        raw_lines = f.read().split(b"\n")

