def load_state():
    try:
        with open(STATE, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    out = {}
    for k, v in data.items():
        if isinstance(v, int) and not isinstance(v, bool):
            out[k] = v
    return out


def save_state(state):
    with open(STATE, "w", encoding="utf-8") as f:
        json.dump(state, f, sort_keys=True)


def read_records():
    path = os.path.join(INPUT, "records.jsonl")
    with open(path, "rb") as f:
        raw = f.read()
    invalid = []
    last = {}  # id -> (version, body bytes)
    for n, line in enumerate(raw.split(b"\n"), 1):
        s = line.strip()
        if not s:
            continue
        rec = None
        try:
            obj = json.loads(s.decode("utf-8"))
            if (isinstance(obj, dict)
                    and isinstance(obj.get("id"), str)
                    and type(obj.get("version")) is int):
                rec = obj
        except (UnicodeDecodeError, ValueError, RecursionError):
            rec = None
        if rec is None:
            invalid.append(n)
        else:
            last[rec["id"]] = (rec["version"], s)
    return invalid, last


def put(record_id, body):
    """Return the HTTP status, or None if there was no response."""
    url = API + "/records/" + urllib.parse.quote(record_id, safe="")
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={
            "content-type": "application/json",
            "Authorization": "Bearer " + API_KEY,
        },
    )
    try:
        with urllib.request.urlopen(req) as resp:
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    invalid, last = read_records()
    for n in invalid:
        print(f"line {n} invalid")

    state = load_state()
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    for rid in sorted(last, key=lambda s: s.encode("utf-8")):
        version, body = last[rid]
        prev = state.get(rid)
        if prev is not None and version <= prev:
            counts["unchanged"] += 1
            print(f"{rid} unchanged")
