            # 5xx, other codes, or no response: retry
        if outcome is None:
            outcome = "failed"

        if outcome == "synced":
            counts["synced"] += 1
            state[rid] = version
            save_state(state)
        elif outcome.startswith("rejected"):
            counts["rejected"] += 1
        else:
            counts["failed"] += 1

        print(f"{rid} {outcome}")

    print(
