# does not send that manifest request. It sends only the PUT requests the spec
# describes.

import json
import os
import urllib.error
import urllib.parse
import urllib.request


def send(api, key, rec_id, body):
    """PUT one record. Returns the HTTP status, or None if there was no response."""
    url = api + "/records/" + urllib.parse.quote(rec_id, safe="")
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={
            "Authorization": "Bearer " + key,
            "content-type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status
    except urllib.error.HTTPError as e:
        return e.code
    except Exception:
        return None


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")
    key = os.environ["API_KEY"]

    # Load the state: id -> last version pushed successfully in an earlier run.
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            st = json.load(f)
        if not isinstance(st, dict):
            st = {}
    except Exception:
        st = {}

    # Read and validate the records file.
    with open(os.path.join(input_dir, "records.jsonl"), "rb") as f:
        data = f.read()

    invalid = []   # line numbers of invalid lines
    last = {}      # id -> (version, raw line); the last valid line of each id wins

    for n, raw in enumerate(data.split(b"\n"), 1):
        try:
            text = raw.decode("utf-8").strip()
        except UnicodeDecodeError:
            invalid.append(n)
            continue
        if not text:
            continue
        try:
            obj = json.loads(text)
        except Exception:
            invalid.append(n)
            continue
        if (
            not isinstance(obj, dict)
            or not isinstance(obj.get("id"), str)
            or not isinstance(obj.get("version"), int)
            or isinstance(obj.get("version"), bool)
        ):
            invalid.append(n)
            continue
        last[obj["id"]] = (obj["version"], text)

    ids = sorted(last, key=lambda s: s.encode("utf-8"))
    results = {}

    for rec_id in ids:
        version, raw_line = last[rec_id]
        prev = st.get(rec_id)
        if prev is not None and version <= prev:
            results[rec_id] = ("unchanged",)
            continue

        outcome = ("failed",)
        for _attempt in range(3):
            code = send(api, key, rec_id, raw_line.encode("utf-8"))
            if code is not None and 200 <= code < 300:
                outcome = ("synced",)
                st[rec_id] = version
                break
            if code is not None and 400 <= code < 500:
                outcome = ("rejected", str(code))
                break
            # 5xx, other statuses, or no response: retry, up to 3 attempts.
        results[rec_id] = outcome

    # Save the state. Only successful pushes changed it.
    try:
        with open(state_path, "w", encoding="utf-8") as f:
            json.dump(st, f)
    except Exception:
        pass

    for n in invalid:
        print(f"line {n} invalid")

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rec_id in ids:
        r = results[rec_id]
        counts[r[0]] += 1
        if r[0] == "rejected":
            print(f"{rec_id} rejected {r[1]}")
        else:
            print(f"{rec_id} {r[0]}")

    print(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )


if __name__ == "__main__":
