    results = {}   # id -> (status, detail)
    pending = []
    for rid, (version, _body) in latest.items():
        prev = last.get(rid)
        if prev is None or version > prev:
            pending.append(rid)
        else:
            results[rid] = ("unchanged", None)

    new_state = dict(last)
    for rid in sorted(pending, key=sort_key):
        version, body = latest[rid]
        outcome = ("failed", None)
        for _attempt in range(3):
            status = put_record(api, api_key, rid, body)
            if status is not None and 200 <= status < 300:
                outcome = ("synced", None)
                break
            if status is not None and 400 <= status < 500:
                outcome = ("rejected", status)
                break
            # 5xx, other non-2xx, or no response: retry
        results[rid] = outcome
        if outcome[0] == "synced":
            new_state[rid] = version

    with open(state_path, "w", encoding="utf-8") as f:
        json.dump(new_state, f, sort_keys=True)

    out = [f"line {n} invalid" for n in invalid]
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(latest, key=sort_key):
        status, detail = results[rid]
        counts[status] += 1
        if status == "rejected":
            out.append(f"{rid} rejected {detail}")
        else:
            out.append(f"{rid} {status}")
    out.append(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8"))
    sys.stdout.flush()


if __name__ == "__main__":
    main()

