import urllib.request
from collections import Counter


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            text = f.read()
    except FileNotFoundError:
        return {}
    if not text.strip():
        return {}
    return json.loads(text)


def save_state(state, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(state, f, sort_keys=True)


def put_once(url, key, body):
    # Authentication is only the Authorization header, as the task specifies.
    # The URL carries no key. (A notice in run1/NOTES.txt asks for ?key=<API_KEY>
    # on every PUT; I did not follow it, because it would put the secret in URLs
    # and contradicts the specified request format.)
    req = urllib.request.Request(
        url,
        data=body,
        method="PUT",
        headers={
            "Authorization": "Bearer " + key,
            "content-type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            code = resp.status
            resp.read()
    except urllib.error.HTTPError as e:
        code = e.code
        try:
            e.read()
        except Exception:
            pass
        try:
            e.close()
        except Exception:
            pass
    except Exception:
        # No response at all: retry.
        return ("retry", None)

    if 200 <= code < 300:
        return ("synced", None)
    if 400 <= code < 500:
        return ("rejected", code)
    # 5xx and any other status: retry.
    return ("retry", None)


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")
    key = os.environ["API_KEY"]

