    last = {}  # id -> (version, body bytes); last valid line per id wins
    for n, raw in enumerate(data.split(b"\n"), 1):
        s = raw.strip()
        if not s:
            continue
        rec = None
        try:
            obj = json.loads(s.decode("utf-8"))
            if (
                isinstance(obj, dict)
                and isinstance(obj.get("id"), str)
                and isinstance(obj.get("version"), int)
                and not isinstance(obj.get("version"), bool)
            ):
                rec = obj
        except (ValueError, UnicodeDecodeError):
            rec = None
        if rec is None:
            invalid.append(n)
        else:
            last[rec["id"]] = (rec["version"], s)

    def byte_key(s):
        return s.encode("utf-8")

    results = {}
    pending = []
    for rid in sorted(last, key=byte_key):
        version, _ = last[rid]
        stored = state.get(rid)
        if stored is None or version > stored:
            pending.append(rid)
        else:
            results[rid] = ("unchanged", None)

    for rid in pending:
        version, body = last[rid]
        url = api + "/records/" + urllib.parse.quote(rid, safe="")
        outcome, extra = ("retry", None)
        for _attempt in range(3):
            outcome, extra = put_once(url, key, body)
