        if outcome == "synced":
            state[rid] = version
            save_state(state, state_path)
            results[rid] = ("synced", None)
        elif outcome == "rejected":
            results[rid] = ("rejected", extra)
        else:
            results[rid] = ("failed", None)

    for n in invalid:
        print(f"line {n} invalid")

    counts = Counter()
    for rid in sorted(last, key=byte_key):
        status, extra = results[rid]
        counts[status] += 1
        if status == "rejected":
