import os
import sys

sys.setrecursionlimit(10000)

LO = -(1 << 63)
HI = (1 << 63) - 1
ARITY = {"min": 2, "max": 2, "abs": 1}


class Syntax(Exception):
    pass


class Calc(Exception):
    def __init__(self, msg):
        super().__init__(msg)
        self.msg = msg


def check(v):
    if v < LO or v > HI:
        raise Calc("overflow")
    return v


def is_digit(c):
    return "0" <= c <= "9"


def is_name_start(c):
    return ("a" <= c <= "z") or ("A" <= c <= "Z") or c == "_"


def is_name_char(c):
    return is_name_start(c) or is_digit(c)


def tokenize(line):
    toks = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in " \t":
            i += 1
        elif c in "+-*/%^(),=":
            toks.append(("op", c))
            i += 1
        elif is_digit(c):
            j = i
            while j < n and is_digit(line[j]):
                j += 1
            toks.append(("int", line[i:j]))
            i = j
        elif is_name_start(c):
            j = i + 1
            while j < n and is_name_char(line[j]):
                j += 1
            toks.append(("name", line[i:j]))
            i = j
        else:
            raise Syntax()
    return toks


class Parser:
    def __init__(self, toks):
        self.toks = toks
        self.pos = 0

    def peek(self):
        return self.toks[self.pos] if self.pos < len(self.toks) else None

    def advance(self):
        t = self.peek()
        if t is None:
            raise Syntax()
        self.pos += 1
        return t

    def is_op(self, s):
        t = self.peek()
        return t is not None and t[0] == "op" and t[1] == s

    def expect_op(self, s):
        if not self.is_op(s):
            raise Syntax()
        self.pos += 1

    def expect_name(self):
        t = self.advance()
        if t[0] != "name":
            raise Syntax()
        return t[1]

    def end(self):
        if self.pos != len(self.toks):
            raise Syntax()

    def expr(self):
        node = self.term()
        while self.is_op("+") or self.is_op("-"):
            op = self.advance()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.is_op("*") or self.is_op("/") or self.is_op("%"):
            op = self.advance()[1]
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.is_op("-"):
            self.advance()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_op("^"):
            self.advance()
            return ("pow", a, self.factor())
        return a

    def atom(self):
        t = self.advance()
        if t[0] == "int":
            return ("num", t[1])
        if t[0] == "name":
            if self.is_op("("):
                self.advance()
                args = [self.expr()]
                while self.is_op(","):
                    self.advance()
                    args.append(self.expr())
                self.expect_op(")")
                return ("call", t[1], args)
            return ("var", t[1])
        if t == ("op", "("):
            e = self.expr()
            self.expect_op(")")
            return e
        raise Syntax()


def powx(a, b):
    if b < 0:
        raise Calc("negative exponent")
    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise Calc("overflow")
    return check(a ** b)


def ev(node, env):
    k = node[0]
    if k == "num":
        digits = node[1].lstrip("0") or "0"
        if len(digits) > 19:
            raise Calc("overflow")
        return check(int(digits))
    if k == "var":
        name = node[1]
        if name not in env:
            raise Calc("unknown variable " + name)
        return env[name]
    if k == "call":
        name, args = node[1], node[2]
        if name not in ARITY:
            raise Calc("unknown function " + name)
        if len(args) != ARITY[name]:
            raise Calc("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return check(abs(vals[0]))
    if k == "neg":
        return check(-ev(node[1], env))
    if k == "pow":
        a = ev(node[1], env)
        b = ev(node[2], env)
        return powx(a, b)
    if k == "bin":
        op = node[1]
        a = ev(node[2], env)
        b = ev(node[3], env)
        if op == "+":
            return check(a + b)
        if op == "-":
            return check(a - b)
        if op == "*":
            return check(a * b)
        if b == 0:
            raise Calc("division by zero")
        if op == "/":
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            return check(q)
        # op == "%"
        m = abs(a) % abs(b)
        if a < 0:
            m = -m
        return m
    raise Calc("syntax error")


def main():
    indir = os.environ["INPUT"]
    with open(os.path.join(indir, "program.txt"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")

    env = {}
    out = []
    for lineno, raw in enumerate(text.split("\n"), 1):
        line = raw[:-1] if raw.endswith("\r") else raw
        if not line.strip(" \t"):
            continue
        try:
            toks = tokenize(line)
            is_let = bool(toks) and toks[0] == ("name", "let")
            p = Parser(toks)
            if is_let:
                p.advance()
                name = p.expect_name()
                p.expect_op("=")
                node = p.expr()
                p.end()
            else:
                node = p.expr()
                p.end()
        except (Syntax, RecursionError):
            out.append(f"{lineno}: error: syntax error")
            continue
        try:
            v = ev(node, env)
            if is_let:
                env[name] = v
                out.append(f"{lineno}: {name} = {v}")
            else:
                out.append(f"{lineno}: {v}")
        except Calc as e:
            out.append(f"{lineno}: error: {e.msg}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")


