ALNUM = LETTERS + DIGITS
SPACES = " \t\r\f\v"
FUNCS = {"min": 2, "max": 2, "abs": 1}


class SyntaxErr(Exception):
    pass


class CalcErr(Exception):
    pass


def tokenize(line):
    toks = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in SPACES:
            i += 1
        elif c in DIGITS:
            j = i
            while j < n and line[j] in DIGITS:
                j += 1
            s = line[i:j].lstrip("0") or "0"
            toks.append(("INT", s))
            i = j
        elif c in LETTERS:
            j = i
            while j < n and line[j] in ALNUM:
                j += 1
            toks.append(("NAME", line[i:j]))
            i = j
        elif c in "+-*/%^(),=":
            toks.append((c, c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.i = 0

    def peek(self):
        return self.t[self.i][0] if self.i < len(self.t) else None

    def next(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise SyntaxErr()
        return self.next()

    def expr(self):
        node = self.term()
        while self.peek() in ("+", "-"):
            op = self.next()[0]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.peek() in ("*", "/", "%"):
            op = self.next()[0]
            node = ("bin", op, node, self.factor())
        return node

    def factor(self):
        if self.peek() == "-":
            self.next()
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.peek() == "^":
            self.next()
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        k = self.peek()
        if k == "INT":
            return ("int", self.next()[1])
        if k == "NAME":
            name = self.next()[1]
            if self.peek() == "(":
                self.next()
                args = [self.expr()]
                while self.peek() == ",":
                    self.next()
                    args.append(self.expr())
                self.expect(")")
                return ("call", name, args)
            return ("var", name)
        if k == "(":
            self.next()
            node = self.expr()
            self.expect(")")
            return node
        raise SyntaxErr()


def parse_line(line):
    toks = tokenize(line)
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.next()
        name = p.expect("NAME")[1]
        p.expect("=")
        node = p.expr()
        if p.i != len(toks):
            raise SyntaxErr()
        return ("let", name, node)
    node = p.expr()
    if p.i != len(toks):
        raise SyntaxErr()
    return ("expr", node)


