    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b >= 64:
        raise CalcErr("overflow")
    return check(a ** b)


def evaluate(node, env):
    k = node[0]
    if k == "int":
        s = node[1]
        if len(s) > 19:
            raise CalcErr("overflow")
        return check(int(s))
    if k == "var":
