        if len(args) != FUNCS[name]:
            raise CalcErr("wrong number of arguments to " + name)
        vals = [evaluate(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return check(abs(vals[0]))
    if k == "bin":
        op = node[1]
        a = evaluate(node[2], env)
        b = evaluate(node[3], env)
        if op == "+":
            return check(a + b)
        if op == "-":
            return check(a - b)
        if op == "*":
            return check(a * b)
        if op in ("/", "%"):
