        return self.t[self.p] if self.p < len(self.t) else None

    def is_op(self, s):
        tok = self.peek()
        return tok is not None and tok[0] == "OP" and tok[1] == s

    def expect_op(self, s):
        if not self.is_op(s):
            raise SyntaxErr()
        self.p += 1

    def expr(self):
        node = self.term()
        while self.is_op("+") or self.is_op("-"):
            op = self.t[self.p][1]
            self.p += 1
            rhs = self.term()
            node = ("bin", op, node, rhs)
        return node

    def term(self):
        node = self.factor()
        while self.is_op("*") or self.is_op("/") or self.is_op("%"):
            op = self.t[self.p][1]
            self.p += 1
            rhs = self.factor()
            node = ("bin", op, node, rhs)
        return node

    def factor(self):
        if self.is_op("-"):
            self.p += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_op("^"):
            self.p += 1
            b = self.factor()
            return ("bin", "^", a, b)
        return a

    def atom(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxErr()
        kind, val = tok
        if kind == "INT":
            self.p += 1
            return ("int", val)
        if kind == "NAME":
            self.p += 1
            if self.is_op("("):
                self.p += 1
                args = [self.expr()]
                while self.is_op(","):
                    self.p += 1
                    args.append(self.expr())
                self.expect_op(")")
                return ("call", val, args)
            return ("var", val)
        if self.is_op("("):
            self.p += 1
            e = self.expr()
            self.expect_op(")")
            return e
        raise SyntaxErr()


def parse_statement(toks):
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.p = 1
        tok = p.peek()
        if tok is None or tok[0] != "NAME":
            raise SyntaxErr()
        name = tok[1]
        p.p += 1
        p.expect_op("=")
        e = p.expr()
        if p.peek() is not None:
            raise SyntaxErr()
        return ("let", name, e)
    e = p.expr()
    if p.peek() is not None:
        raise SyntaxErr()
    return ("expr", None, e)


def check(v):
    if v < LO or v > HI:
        raise CalcError("overflow")
    return v


def power(a, b):
    if b < 0:
        raise CalcError("negative exponent")
    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b >= 64:
        raise CalcError("overflow")
    return check(a ** b)


ARITY = {"min": 2, "max": 2, "abs": 1}


def ev(node, env):
    k = node[0]
    if k == "int":
        return check(node[1])
    if k == "var":
        name = node[1]
        if name not in env:
            raise CalcError("unknown variable " + name)
        return env[name]
    if k == "neg":
        return check(-ev(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in ARITY:
            raise CalcError("unknown function " + name)
        if len(args) != ARITY[name]:
            raise CalcError("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals[0], vals[1])
        if name == "max":
            return max(vals[0], vals[1])
        return check(abs(vals[0]))
    # binary operation
    _, op, l, r = node
    a = ev(l, env)
    b = ev(r, env)
    if op == "+":
        return check(a + b)
    if op == "-":
        return check(a - b)
    if op == "*":
        return check(a * b)
    if op == "/" or op == "%":
        if b == 0:
            raise CalcError("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        if op == "/":
            return check(q)
        return check(a - b * q)
    # op == "^"
    return power(a, b)


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "program.txt"), "rb") as f:
        text = f.read().decode("latin-1")

    env = {}
    out = []
    count = 0  # N counts non-blank lines, from 1
    for raw in text.split("\n"):
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip(" ") == "":
            continue
        count += 1
        try:
            kind, name, node = parse_statement(tokenize(line))
        except SyntaxErr:
            out.append(f"{count}: error: syntax error")
            continue
        try:
            v = ev(node, env)
        except CalcError as e:
            out.append(f"{count}: error: {e}")
            continue
        if kind == "let":
            env[name] = v
            out.append(f"{count}: {name} = {v}")
        else:
            out.append(f"{count}: {v}")

    if out:
        sys.stdout.write("\n".join(out) + "\n")


