import os
import sys

LO = -(1 << 63)
HI = (1 << 63) - 1


class SyntaxErr(Exception):
    pass


class CalcError(Exception):
    pass


def tokenize(line):
    toks = []
    i = 0
    n = len(line)

    def is_alpha(ch):
        return ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ch == "_"

    def is_digit(ch):
        return "0" <= ch <= "9"

    while i < n:
        c = line[i]
        if c == " ":
            i += 1
        elif c in "+-*/%^()=,":
            toks.append(("OP", c))
            i += 1
        elif is_digit(c):
            j = i
            while j < n and is_digit(line[j]):
                j += 1
            toks.append(("INT", int(line[i:j])))
            i = j
        elif is_alpha(c):
            j = i
            while j < n and (is_alpha(line[j]) or is_digit(line[j])):
                j += 1
            toks.append(("NAME", line[i:j]))
            i = j
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else None

    def is_op(self, s):
        tok = self.peek()
        return tok is not None and tok[0] == "OP" and tok[1] == s

    def expect_op(self, s):
        if not self.is_op(s):
            raise SyntaxErr()
        self.p += 1

    def expr(self):
        node = self.term()
        while self.is_op("+") or self.is_op("-"):
            op = self.t[self.p][1]
            self.p += 1
            rhs = self.term()
            node = ("bin", op, node, rhs)
        return node

    def term(self):
        node = self.factor()
        while self.is_op("*") or self.is_op("/") or self.is_op("%"):
            op = self.t[self.p][1]
            self.p += 1
            rhs = self.factor()
            node = ("bin", op, node, rhs)
        return node

    def factor(self):
        if self.is_op("-"):
            self.p += 1
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_op("^"):
            self.p += 1
            b = self.factor()
            return ("bin", "^", a, b)
        return a

    def atom(self):
        tok = self.peek()
        if tok is None:
            raise SyntaxErr()
        kind, val = tok
        if kind == "INT":
            self.p += 1
            return ("int", val)
        if kind == "NAME":
            self.p += 1
            if self.is_op("("):
                self.p += 1
                args = [self.expr()]
                while self.is_op(","):
                    self.p += 1
                    args.append(self.expr())
                self.expect_op(")")
                return ("call", val, args)
            return ("var", val)
        if self.is_op("("):
            self.p += 1
            e = self.expr()
            self.expect_op(")")
            return e
        raise SyntaxErr()


def parse_statement(toks):
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.p = 1
        tok = p.peek()
        if tok is None or tok[0] != "NAME":
            raise SyntaxErr()
        name = tok[1]
        p.p += 1
        p.expect_op("=")
        e = p.expr()
        if p.peek() is not None:
            raise SyntaxErr()
        return ("let", name, e)
    e = p.expr()
    if p.peek() is not None:
        raise SyntaxErr()
    return ("expr", None, e)


def check(v):
    if v < LO or v > HI:
        raise CalcError("overflow")
    return v


def power(a, b):
    if b < 0:
        raise CalcError("negative exponent")
    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b >= 64:
        raise CalcError("overflow")
    return check(a ** b)


ARITY = {"min": 2, "max": 2, "abs": 1}


def ev(node, env):
    k = node[0]
    if k == "int":
        return check(node[1])
    if k == "var":
        name = node[1]
        if name not in env:
            raise CalcError("unknown variable " + name)
        return env[name]
    if k == "neg":
        return check(-ev(node[1], env))
    if k == "call":
        name, args = node[1], node[2]
        if name not in ARITY:
