        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals[0], vals[1])
        if name == "max":
            return max(vals[0], vals[1])
        return check(abs(vals[0]))
    # binary operation
    _, op, l, r = node
    a = ev(l, env)
    b = ev(r, env)
    if op == "+":
        return check(a + b)
    if op == "-":
        return check(a - b)
    if op == "*":
        return check(a * b)
    if op == "/" or op == "%":
        if b == 0:
