import os
import sys

PAIRS = {")": "(", "]": "[", "}": "{"}
OPENERS = {"(": ")", "[": "]", "{": "}"}


def check(line):
    """Return the diagnostic for one line, or 'ok'."""
    stack = []
    for col, ch in enumerate(line, 1):
        if ch in OPENERS:
            stack.append(ch)
        elif ch in PAIRS:
            if not stack:
                return f"col {col}: unexpected {ch}"
            top = stack.pop()
            if top != PAIRS[ch]:
                return f"col {col}: expected {OPENERS[top]}, found {ch}"
    if stack:
        return f"unclosed {OPENERS[stack[-1]]}"
    return "ok"


