    path = os.path.join(base, "snippets.txt")
    with open(path, "r", encoding="ascii", newline="") as f:
        lines = f.read().splitlines()
    out = [check(line) for line in lines]
    if out:
        sys.stdout.write("\n".join(out) + "\n")


