# The collector's completion sentinel is the final line of the file. Its exact
# text was cut off in the README excerpt I was given, so set this to the literal
# sentinel record from input/README.md before running. The program does not
# start computing until it sees this line, because the window may still be
# draining when the program starts.
SENTINEL = "<SET FROM input/README.md>"

INT_RE = re.compile(r"[0-9]+\Z")


def read_lines():
    with open(PATH, "rb") as f:
        data = f.read()
    return data.decode("utf-8", errors="replace").split("\n")


def wait_for_sentinel():
    while True:
        try:
            lines = [ln.strip() for ln in read_lines()]
        except FileNotFoundError:
            lines = []
        nonempty = [ln for ln in lines if ln]
        if nonempty and nonempty[-1] == SENTINEL:
            return nonempty
        time.sleep(0.5)


def parse(lines):
    groups = {}
    for ln in lines:
        if ln == SENTINEL:
            continue
        parts = ln.split()
        if len(parts) != 3:
            continue
        method, path, millis = parts
        if not INT_RE.match(millis):
