                x, y, c = parts[1], parts[2], int(parts[3])
                adj.setdefault(x, []).append((y, c))
                adj.setdefault(y, []).append((x, c))
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))

