import heapq
import os
import sys


def load(path):
    """Parse routes.txt into an undirected adjacency map and the list of trips."""
    adj = {}
    trips = []
    with open(path, "rb") as f:
        for raw in f:
            line = raw.decode("utf-8", "surrogateescape").strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) == 4:
                x, y, c = parts[1], parts[2], int(parts[3])
                adj.setdefault(x, []).append((y, c))
                adj.setdefault(y, []).append((x, c))
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))
    return adj, trips


def distances_to(target, adj):
    """Shortest distance from every town to `target` (graph is undirected)."""
    dist = {target: 0}
    heap = [(0, target)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist.get(u):
            continue
        for v, w in adj.get(u, ()):
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist


def main():
    adj, trips = load(os.path.join(os.environ["INPUT"], "routes.txt"))
    # Distances are computed per destination on demand. The full all-pairs
    # table from the README (9000x9000 int64, ~648 MB) is not needed to get
    # the answers and would exceed the memory limit, so it is not built.
    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = distances_to(y, adj)
        dist = cache[y]
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        # Greedy walk: at each step take the smallest town that lies on a
        # shortest route to y. Costs are positive, so this yields the
        # lexicographically smallest cheapest route.
        path = [x]
        cur = x
        while cur != y:
            best = None
            for v, w in adj.get(cur, ()):
                if v in dist and dist[v] + w == dist[cur]:
                    if best is None or v < best:
