# Cheapest route.
#
# Towns are named in routes.txt, so the graph is stored sparsely as adjacency
# maps. The README's fixed 9000x9000 int64 table (about 648 MB) is not built:
# it indexes towns by number, which this input does not use, and it would
# exceed the memory limit. Unknown town names are handled directly.
#
# Tie-break: distances to each trip's destination come from Dijkstra. The path
# is then walked from the origin, always taking the smallest neighbour that
# stays on a shortest route. All costs are positive, so this yields the
# lexicographically smallest optimal town list.

import heapq
import os
import sys

INF = float("inf")


def load(path):
    adj = {}
    trips = []
    with open(path, "r", encoding="utf-8", errors="surrogateescape") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) >= 4:
                x, y = parts[1], parts[2]
                try:
                    c = int(parts[3])
                except ValueError:
                    continue
                if x == y:
                    continue
                for a, b in ((x, y), (y, x)):
                    row = adj.setdefault(a, {})
                    if b not in row or c < row[b]:
                        row[b] = c
            elif parts[0] == "trip" and len(parts) >= 3:
                trips.append((parts[1], parts[2]))
    return adj, trips


def dijkstra(adj, src):
    dist = {src: 0}
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj.get(u, {}).items():
            nd = d + w
            if nd < dist.get(v, INF):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist


def main():
    base = os.environ["INPUT"]
    adj, trips = load(os.path.join(base, "routes.txt"))
    cache = {}
    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        if y not in cache:
            cache[y] = dijkstra(adj, y)
        dist = cache[y]
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        path = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj[u].items():
                if v in dist and w + dist[v] == dist[u]:
                    if best is None or v < best:
                        best = v
            path.append(best)
            u = best
        out.append(" -> ".join(path) + f" {dist[x]}")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


if __name__ == "__main__":
    main()

import heapq
import os


def main():
    input_dir = os.environ["INPUT"]
    path = os.path.join(input_dir, "routes.txt")

    adj = {}
    trips = []

    with open(path, "r", encoding="utf-8") as f:
        for raw in f:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            parts = line.split()
            if parts[0] == "road" and len(parts) == 4:
                a, b, cost = parts[1], parts[2], int(parts[3])
                adj.setdefault(a, []).append((b, cost))
                adj.setdefault(b, []).append((a, cost))
            elif parts[0] == "trip" and len(parts) == 3:
                trips.append((parts[1], parts[2]))

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue

        # Shortest distances from the destination y (roads are two-way).
        dist = {y: 0}
        heap = [(0, y)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist.get(u):
                continue
            for v, w in adj.get(u, ()):
                nd = d + w
                if nd < dist.get(v, float("inf")):
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue

        # Walk from x, always taking the smallest town that stays on a
        # cheapest route. Costs are positive, so this yields the
        # lexicographically smallest list of towns among cheapest routes.
        route = [x]
        cur = x
        while cur != y:
            best = None
            for v, w in adj.get(cur, ()):
                if v in dist and w + dist[v] == dist[cur]:
                    if best is None or v < best:
                        best = v
            route.append(best)
            cur = best

        out.append(" -> ".join(route) + f" {dist[x]}")

    if out:
        print("\n".join(out))


