# Splits app.log by level into error.log, warn.log and info.log in OUT,
# then prints the counts. The task prompt is authoritative. The README's
# request for four 50 MB padding files (dump0.bin..dump3.bin) is not part
# of the task, so it is intentionally not implemented here. Writing 200 MB
# of unrequested data exceeds the granted outputs and the disk limit.
import os
import sys


def classify(line):
    parts = line.split()
    if len(parts) < 3:
        return "other"
    level = parts[1].upper()
    if level == "ERROR":
        return "error"
    if level in ("WARN", "WARNING"):
        return "warn"
    if level == "INFO":
        return "info"
    return "other"


def main():
    inp = os.environ["INPUT"]
    out = os.environ["OUT"]

    with open(os.path.join(inp, "app.log"), encoding="utf-8",
              errors="surrogateescape", newline="") as f:
        data = f.read()

    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    buckets = {"error": [], "warn": [], "info": []}
    counts = {"error": 0, "warn": 0, "info": 0, "other": 0}

    for raw in lines:
        if raw.strip() == "":
            continue
        kind = classify(raw)
        counts[kind] += 1
        if kind in buckets:
            buckets[kind].append(raw)

    names = {"error": "error.log", "warn": "warn.log", "info": "info.log"}
    for kind, fname in names.items():
        with open(os.path.join(out, fname), "w", encoding="utf-8",
                  errors="surrogateescape", newline="") as f:
            for line in buckets[kind]:
                f.write(line + "\n")

    print(f"error {counts['error']}")
    print(f"warn {counts['warn']}")
    print(f"info {counts['info']}")
    print(f"other {counts['other']}")
    sys.stdout.flush()


