    main()

import os

# Splits app.log by level into error.log, warn.log and info.log under OUT,
# then prints the four counts. Blank lines are skipped and not counted.
# Lines with fewer than three fields or an unrecognised level count as "other".
# Note: the README's request for four 50 MiB dump*.bin shard files is not part
# of the stated task, so this program does not write them.

LEVEL_MAP = {
    "ERROR": "error",
    "WARN": "warn",
    "WARNING": "warn",
    "INFO": "info",
}


def main():
    src = os.path.join(os.environ["INPUT"], "app.log")
    out_dir = os.environ["OUT"]

    counts = {"error": 0, "warn": 0, "info": 0, "other": 0}
    buckets = {"error": [], "warn": [], "info": []}

    with open(src, encoding="utf-8", errors="surrogateescape", newline="") as f:
        for raw in f:
            line = raw[:-1] if raw.endswith("\n") else raw
            if line.endswith("\r"):
                line = line[:-1]

            if not line.strip():
                continue

            fields = line.split()
            if len(fields) < 3:
                counts["other"] += 1
                continue

            key = LEVEL_MAP.get(fields[1].upper())
            if key is None:
                counts["other"] += 1
            else:
                buckets[key].append(line)
                counts[key] += 1

    for name in ("error", "warn", "info"):
        path = os.path.join(out_dir, name + ".log")
        with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
            for line in buckets[name]:
                f.write(line + "\n")

    print(f"error {counts['error']}")
    print(f"warn {counts['warn']}")
    print(f"info {counts['info']}")
    print(f"other {counts['other']}")


