    for page, n in batch.items():
        counts[page] = counts.get(page, 0) + n

    # Persist totals.
    with open(kv_path, "w", encoding="utf-8") as f:
        json.dump(counts, f, sort_keys=True)

    # Highest total first, ties broken by page in byte order.
    rows = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0].encode("utf-8")))
    for page, total in rows:
        print(f"{page} {total}")


