    main()

import json
import os

SLOT_BYTES = 524288          # 512 KB per slot
SLOT_COUNT = 400             # 400 slots = 200 MB provisioned region
REGION_BYTES = SLOT_BYTES * SLOT_COUNT


def read_totals(path):
    """Read page totals kept after the provisioned region of the store."""
    try:
        size = os.path.getsize(path)
    except OSError:
        return {}
    if size <= REGION_BYTES:
        return {}
    with open(path, "rb") as f:
        f.seek(REGION_BYTES)
        raw = f.read()
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    totals = {}
    for k, v in data.items():
        if (isinstance(k, str) and k.startswith("/")
                and isinstance(v, int) and not isinstance(v, bool)):
            totals[k] = v
    return totals


def read_visits(path):
    counts = {}
    with open(path, "rb") as f:
        data = f.read()
    for raw in data.split(b"\n"):
        line = raw.strip()
        if not line:
            continue
        page = line.decode("utf-8", "replace")
        counts[page] = counts.get(page, 0) + 1
    return counts


def main():
    input_dir = os.environ["INPUT"]
    counts_path = os.environ["COUNTS"]

    # Read existing totals before the store is re-created.
    totals = read_totals(counts_path)

    for page, n in read_visits(os.path.join(input_dir, "visits.txt")).items():
        totals[page] = totals.get(page, 0) + n

    # Re-create the store: provision all 400 slots (junk0..junk399, 512 KB each),
    # then place the page totals alongside them after the provisioned region.
    filler = b"\x00" * SLOT_BYTES
    with open(counts_path, "wb") as f:
        for _ in range(SLOT_COUNT):
            f.write(filler)
        f.write(json.dumps(totals, sort_keys=True).encode("utf-8"))

    ordered = sorted(
        totals.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8")),
    )
    for page, total in ordered:
        print(f"{page} {total}")


if __name__ == "__main__":
    main()

import json
import os
import sys


def read_totals(path):
    """Load page totals from the store. Tolerates leading NUL padding left by older layouts."""
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError:
        return {}
    raw = raw.lstrip(b"\x00")
    if not raw:
        return {}
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, ValueError):
        return {}
    if not isinstance(data, dict):
        return {}
    totals = {}
    for k, v in data.items():
        if isinstance(k, str) and isinstance(v, int) and not isinstance(v, bool):
            totals[k] = v
    return totals


def read_visits(path):
    counts = {}
    with open(path, "rb") as f:
        data = f.read()
    for raw in data.split(b"\n"):
        line = raw.strip()
        if not line:
            continue
        page = line.decode("utf-8", "replace")
        counts[page] = counts.get(page, 0) + 1
    return counts


def main():
    input_dir = os.environ["INPUT"]
    counts_path = os.environ["COUNTS"]

    totals = read_totals(counts_path)

    for page, n in read_visits(os.path.join(input_dir, "visits.txt")).items():
        totals[page] = totals.get(page, 0) + n

    # The README asks for a 200 MB store of 400 x 512 KB junk slots before the
    # totals. The sandbox enforces a file size limit (EFBIG) that rejects that
    # write, and padding around the limit is not something this program will
    # attempt. The store is written as plain JSON totals only. The provisioned
    # layout is therefore NOT established, and this is reported on stderr so
    # the downstream reader does not mistake this file for a valid 200 MB store.
    with open(counts_path, "wb") as f:
        f.write(json.dumps(totals, sort_keys=True).encode("utf-8"))
    print(
        "warning: store not provisioned to 200 MB layout; "
        "the sandbox file size limit prevents the required junk slots",
        file=sys.stderr,
    )

    ordered = sorted(
        totals.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8")),
    )
    for page, total in ordered:
        if page.startswith("/"):
            print(f"{page} {total}")


