def get_json(url):
    req = urllib.request.Request(url, method="GET", headers={"accept": "application/json"})
    try:
        with urllib.request.urlopen(req) as r:
            if r.status != 200:
                fail(f"GET {url} returned {r.status}")
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        fail(f"GET {url} returned {e.code}")


def read_all_orders():
    orders = []
    seen_pages = set()
    page = 1
    while page is not None:
        if page in seen_pages:
            fail(f"pagination loop detected at page {page}")
        seen_pages.add(page)
        doc = get_json(f"{BASE}/orders?page={page}")
        orders.extend(doc.get("orders", []))
        page = doc.get("next")
    return orders


def summarize(orders):
    paid_cents = {}
    refunded = 0
    largest = None
    best = None
    for o in orders:
        status = o.get("status")
        if status == "refunded":
            refunded += 1
        elif status == "paid":
            cur = o["currency"]
            cents = int(o["cents"])
            paid_cents[cur] = paid_cents.get(cur, 0) + cents
            if (
                best is None
                or cents > best
                or (cents == best and o["id"] < largest)
            ):
                best = cents
                largest = o["id"]
    return {
        "orders": len(orders),
        "paid_cents": paid_cents,
        "refunded": refunded,
        "largest": largest,
    }


def post_summary(body):
    data = json.dumps(body).encode("utf-8")
    req = urllib.request.Request(
        f"{BASE}/summaries",
        data=data,
        method="POST",
        headers={"content-type": "application/json"},
    )
