        with urllib.request.urlopen(req) as r:
            status = r.status
            payload = r.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        fail(f"POST /summaries returned {e.code}")
    if status != 201:
        fail(f"POST /summaries returned {status}")
    try:
        return json.loads(payload)["id"]
    except (ValueError, KeyError):
        fail("POST /summaries response has no id")


def main():
    orders = read_all_orders()
    body = summarize(orders)
    summary_id = post_summary(body)
    print(summary_id)


