import json
import os
import urllib.error
import urllib.parse
import urllib.request


def parse_line(raw):
    """Return (id, version, body_bytes) for a valid record line, else None."""
    try:
        text = raw.decode("utf-8")
        obj = json.loads(text)
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    rid = obj.get("id")
    ver = obj.get("version")
    if not isinstance(rid, str):
        return None
    if not isinstance(ver, int) or isinstance(ver, bool):
        return None
    return rid, ver, text.strip().encode("utf-8")


def push(api, rid, body):
    """Return (status, code). status is synced, rejected, or failed."""
    url = api + "/records/" + urllib.parse.quote(rid, safe="")
    for _ in range(3):
        req = urllib.request.Request(
            url,
            data=body,
            method="PUT",
            headers={"content-type": "application/json"},
        )
        code = None
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                code = resp.getcode()
        except urllib.error.HTTPError as e:
            code = e.code
            try:
                e.close()
            except Exception:
                pass
        except Exception:
            code = None  # no response at all: retry

        if code is not None:
            if 200 <= code < 300:
                return "synced", code
            if 400 <= code < 500:
                return "rejected", code
        # 5xx, other status, or no response: retry
    return "failed", None


def load_state(path):
    if not os.path.exists(path):
        return {}
    with open(path, "rb") as f:
        raw = f.read()
    if not raw.strip():
        return {}
    data = json.loads(raw.decode("utf-8"))
    return dict(data) if isinstance(data, dict) else {}


def save_state(path, state):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(state, f, sort_keys=True)


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    api = os.environ["API"].rstrip("/")

    state = load_state(state_path)

    with open(os.path.join(input_dir, "records.jsonl"), "rb") as f:
        data = f.read()

    invalid = []
    last = {}  # id -> (version, body) of its last valid line
    for n, raw_line in enumerate(data.split(b"\n"), 1):
        if not raw_line.strip():
            continue
        rec = parse_line(raw_line)
        if rec is None:
            invalid.append(n)
        else:
            rid, ver, body = rec
            last[rid] = (ver, body)

    results = {}
    for rid in sorted(last, key=lambda s: s.encode("utf-8")):
        ver, body = last[rid]
        prev = state.get(rid)
        if prev is not None and ver <= prev:
            results[rid] = ("unchanged", None)
            continue
        status, code = push(api, rid, body)
        results[rid] = (status, code)
        if status == "synced":
            state[rid] = ver
            save_state(state_path, state)

    for n in invalid:
        print(f"line {n} invalid")

    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}
    for rid in sorted(results, key=lambda s: s.encode("utf-8")):
        status, code = results[rid]
        counts[status] += 1
        if status == "rejected":
            print(f"{rid} rejected {code}")
        else:
            print(f"{rid} {status}")

    print(
        f"synced {counts['synced']} unchanged {counts['unchanged']} "
        f"rejected {counts['rejected']} failed {counts['failed']}"
    )


