import os
import sys

LO = -(1 << 63)
HI = (1 << 63) - 1


class SyntaxErr(Exception):
    pass


class CalcErr(Exception):
    pass


OPS = set("+-*/%^(),=")
DIG = set("0123456789")
ALPHA = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
ALNUM = ALPHA | DIG
FUNCS = {"min": 2, "max": 2, "abs": 1}


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in (" ", "\t"):
            i += 1
        elif c in DIG:
            j = i
            while j < n and s[j] in DIG:
                j += 1
            toks.append(("INT", s[i:j]))
            i = j
        elif c in ALPHA:
            j = i
            while j < n and s[j] in ALNUM:
                j += 1
            toks.append(("NAME", s[i:j]))
            i = j
        elif c in OPS:
            toks.append(("OP", c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else None

    def is_op(self, ch):
        tk = self.peek()
        return tk is not None and tk[0] == "OP" and tk[1] == ch

    def take_op(self, ch):
        if self.is_op(ch):
            self.p += 1
            return True
        return False

    def expect_op(self, ch):
        if not self.take_op(ch):
            raise SyntaxErr()

    def expr(self):
        node = self.term()
        while True:
            if self.take_op("+"):
                node = ("bin", "+", node, self.term())
            elif self.take_op("-"):
                node = ("bin", "-", node, self.term())
            else:
                return node

    def term(self):
        node = self.factor()
        while True:
            if self.take_op("*"):
                node = ("bin", "*", node, self.factor())
            elif self.take_op("/"):
                node = ("bin", "/", node, self.factor())
            elif self.take_op("%"):
                node = ("bin", "%", node, self.factor())
            else:
                return node

    def factor(self):
        if self.take_op("-"):
            return ("neg", self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.take_op("^"):
            return ("bin", "^", a, self.factor())
        return a

    def atom(self):
        tk = self.peek()
        if tk is None:
            raise SyntaxErr()
        if tk[0] == "INT":
            self.p += 1
            return ("num", tk[1])
        if tk[0] == "NAME":
            self.p += 1
            if self.take_op("("):
                args = [self.expr()]
                while self.take_op(","):
                    args.append(self.expr())
                self.expect_op(")")
                return ("call", tk[1], args)
            return ("var", tk[1])
        if self.take_op("("):
            e = self.expr()
            self.expect_op(")")
            return e
        raise SyntaxErr()


def parse_line(s):
    toks = tokenize(s)
    p = Parser(toks)
    if toks and toks[0] == ("NAME", "let"):
        p.p = 1
        tk = p.peek()
        if tk is None or tk[0] != "NAME":
            raise SyntaxErr()
        name = tk[1]
        p.p += 1
        p.expect_op("=")
        e = p.expr()
        if p.peek() is not None:
            raise SyntaxErr()
        return ("let", name, e)
    e = p.expr()
    if p.peek() is not None:
        raise SyntaxErr()
    return ("expr", e)


def chk(v):
    if v < LO or v > HI:
        raise CalcErr("overflow")
    return v


def ev(node, env):
    k = node[0]
    if k == "num":
        s = node[1].lstrip("0")
        if len(s) > 19:
            raise CalcErr("overflow")
        return chk(int(s or "0"))
    if k == "var":
        if node[1] not in env:
            raise CalcErr("unknown variable " + node[1])
        return env[node[1]]
    if k == "call":
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise CalcErr("unknown function " + name)
        if len(args) != FUNCS[name]:
            raise CalcErr("wrong number of arguments to " + name)
        vals = [ev(a, env) for a in args]
        if name == "min":
            return min(vals)
        if name == "max":
            return max(vals)
        return chk(abs(vals[0]))
    if k == "neg":
        return chk(-ev(node[1], env))
    # binary operators
    op, left, right = node[1], node[2], node[3]
    a = ev(left, env)
    b = ev(right, env)
    if op == "+":
        return chk(a + b)
    if op == "-":
        return chk(a - b)
    if op == "*":
        return chk(a * b)
    if op == "/":
        if b == 0:
            raise CalcErr("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return chk(q)
    if op == "%":
        if b == 0:
            raise CalcErr("division by zero")
        m = abs(a) % abs(b)
        return -m if a < 0 else m
    # "^"
    if b < 0:
        raise CalcErr("negative exponent")
    if a == 0:
        return 1 if b == 0 else 0
    if a == 1:
        return 1
    if a == -1:
        return 1 if b % 2 == 0 else -1
    if b > 64:
        raise CalcErr("overflow")
    return chk(a ** b)


def main():
    sys.setrecursionlimit(10000)
    d = os.environ["INPUT"]
    with open(os.path.join(d, "program.txt"), "rb") as f:
        text = f.read().decode("utf-8", errors="replace")
    env = {}
    out = []
    for no, line in enumerate(text.split("\n"), 1):
        line = line.rstrip("\r")
        if line.strip(" \t") == "":
            continue
        try:
            st = parse_line(line)
            if st[0] == "let":
                v = ev(st[2], env)
                env[st[1]] = v
                out.append(f"{no}: {st[1]} = {v}")
            else:
                out.append(f"{no}: {ev(st[1], env)}")
        except SyntaxErr:
            out.append(f"{no}: error: syntax error")
        except CalcErr as e:
            out.append(f"{no}: error: {e}")
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


